// Üretilen dosya: tool/ozgun/uret.py. Fizik · Elektrik devreleri ve elektrik enerjisi hesapları (orta).
const ozPhysics11Orta = <(String, String, List<String>, String)>[
  ('Bir iletkenin kesitinden 2 dakikada 1,2 × 10²¹ elektron geçiyor. Ortalama akım şiddeti kaç amperdir? (e = 1,6 × 10⁻¹⁹ C)', '1,6 A', ['0,8 A', '0,16 A', '16 A'], 'Yük q = 1,2×10²¹ × 1,6×10⁻¹⁹ = 192 C; süre 120 s olduğundan I = 192/120 = 1,6 A bulunur.'),
  ('Aynı maddeden yapılmış iki telden geçen akım eşittir. Birinin yarıçapı r, diğerinin 2r ise yarıçapı r olan telde elektronların sürüklenme hızı, diğerindekinin kaç katıdır?', '4 katı', ['2 katı', 'Yarısı', 'Aynı kalır'], 'Sürüklenme hızı v = I/(nAe) ile ters orantılıdır. Alan yarıçapın karesi ile orantılı olduğundan ince telde alan dörtte biridir, hız dört katıdır.'),
  ('Bir iletkenden geçen akım zamana bağlı olarak I = 2t (I amper, t saniye) bağıntısıyla artmaktadır. İlk 4 saniyede iletkenin kesitinden geçen yük kaç coulombdur?', '16 C', ['8 C', '32 C', '12,5 C'], 'Yük, akım-zaman grafiğinin altındaki alandır. 0–4 s arasında alan, taban 4 s ve yükseklik 8 A olan üçgenin alanı, yani ½·4·8 = 16 C\'dir.'),
  ('Kesit alanı 1,5 mm² olan bir telden 3 A akım geçmektedir. Telin içindeki akım yoğunluğu kaç A/m²\'dir?', '2 × 10⁶ A/m²', ['2 × 10³ A/m²', '4,5 × 10⁶ A/m²', '5 × 10⁵ A/m²'], 'J = I/A = 3 / (1,5×10⁻⁶ m²) = 2×10⁶ A/m² bulunur. Alan mm²\'den m²\'ye çevrilmelidir.'),
  ('Nominal gerilimi 3,7 V ve kapasitesi 3000 mAh olan bir pilde depolanan enerji yaklaşık kaç watt-saattir?', '11,1 Wh', ['1,1 Wh', '8,1 Wh', '0,111 Wh'], 'Enerji = gerilim × kapasite = 3,7 V × 3 Ah = 11,1 Wh\'dir.'),
  ('Bir parçacık hızlandırıcıda saniyede 5 × 10¹⁶ proton içeren bir demet ilerlemektedir. Demetin oluşturduğu akım kaç miliamperdir? (e = 1,6 × 10⁻¹⁹ C)', '8 mA', ['0,8 mA', '80 mA', '3,2 mA'], 'I = 5×10¹⁶ × 1,6×10⁻¹⁹ = 8×10⁻³ A = 8 mA\'dir.'),
  ('Bir yıldırım olayında 2 × 10⁴ A\'lik akım yaklaşık 200 μs sürmektedir. Bu sürede aktarılan yük kaç coulombdur?', '4 C', ['0,4 C', '40 C', '100 C'], 'q = I·t = 2×10⁴ A × 2×10⁻⁴ s = 4 C\'dir.'),
  ('Coulomb biriminin SI temel birimleri cinsinden karşılığı aşağıdakilerden hangisidir?', 'A·s', ['A/s', 'W·s/A', 'J/A'], 'I = q/t olduğundan q = I·t\'dir; yani 1 C = 1 A·s\'dir.'),
  ('Kesiti değişken bir tel, kalın bölümünde A, ince bölümünde A/3 kesit alanına sahiptir. Telden sabit akım geçerken ince bölümdeki sürüklenme hızı kalın bölümdekinin kaç katıdır?', '3 katı', ['1/3 katı', '9 katı', '1 katı'], 'Akım telin her yerinde aynıdır; v = I/(nAe) olduğundan alanı üçte bire inen bölümde sürüklenme hızı üç katına çıkar.'),
  ('Tek ilmekli bir devrede ardışık dirençlerin her kesitinden aynı büyüklükte akım geçmesi hangi ilkenin sonucudur?', 'Yükün korunumu ve yükün düğümlerde birikmemesi', ['Enerjinin korunumu', 'Direncin sıcaklıkla artmasının yük akışını sınırlaması', 'Potansiyelin her yerde aynı olması'], 'Kararlı durumda devrenin hiçbir noktasında yük birikmez; bu yüzden birim sürede bir kesitten geçen yük her kesitte aynıdır.'),
  ('Bir telefon şarj cihazı 5 V gerilimde 2 A akım sağlamaktadır. Bir saatte cihazdan geçen yük kaç coulombdur?', '7200 C', ['120 C', '600 C', '36 000 C'], 'Süre 3600 s; q = 2 A × 3600 s = 7200 C\'dir. Gerilim yükü etkilemez, yalnız enerjiyi belirler.'),
  ('Aynı maddeden iki telden birinin uzunluğu L, kesit alanı A; diğerinin uzunluğu 2L, kesit alanı 2A\'dır. Dirençleri oranı R₁/R₂ kaçtır?', '1', ['1/2', '2', '4'], 'R₁ = ρL/A ve R₂ = ρ(2L)/(2A) = ρL/A olduğundan iki direnç birbirine eşittir; oran 1\'dir.'),
  ('20 °C\'de direnci 100 Ω olan bir metal telin direnç sıcaklık katsayısı 4 × 10⁻³ /°C\'dir. Tel 70 °C\'ye ısıtılırsa direnci kaç ohm olur?', '120 Ω', ['104 Ω', '140 Ω', '1200 Ω'], 'R = R₀(1 + αΔT) = 100 (1 + 4×10⁻³ × 50) = 100 × 1,2 = 120 Ω olur.'),
  ('Bir iletkenin uçlarına 6 V uygulandığında 0,3 A, 9 V uygulandığında 0,45 A akım geçmektedir. Bu iletken için ne söylenebilir?', 'Omik bir iletkendir, direnci 20 Ω\'dur', ['Omik değildir, çünkü akım gerilimle artmaktadır', 'Omik bir iletkendir, direnci 2 Ω\'dur', 'Omik değildir, direnci artan gerilimle büyümektedir'], 'V/I oranı iki durumda da 20 Ω\'dur (6/0,3 = 9/0,45). Oranın sabit olması iletkenin omik olduğunu gösterir.'),
  ('Sarı, mor, kırmızı ve altın renk bantlı bir direncin değeri ve toleransı nedir? (Sarı 4, mor 7, kırmızı ×100, altın %5)', '4700 Ω, ±%5', ['470 Ω, ±%5', '4700 Ω, ±%10', '47 000 Ω, ±%5'], 'İlk iki bant 4 ve 7, üçüncü bant çarpan ×10² olduğundan 47 × 100 = 4700 Ω; altın bant ±%5 toleransı gösterir.'),
  ('Uzunluğu 10 m olan düzgün bir telin uçlarına 20 V gerilim uygulanıyor. Telin içindeki elektrik alan şiddeti kaç V/m\'dir?', '2 V/m', ['200 V/m', '0,5 V/m', '10 V/m'], 'Düzgün bir iletkende alan E = V/L = 20 / 10 = 2 V/m\'dir.'),
  ('Silindirik bir telin hem uzunluğu hem çapı yarıya indiriliyor. Yeni direnç ilk direncin kaç katı olur?', '2 katı', ['1/2 katı', '4 katı', 'Aynı kalır'], 'Uzunluk yarıya inince R yarıya, çap yarıya inince alan dörtte bire iner ve R dört katına çıkar. Net etki 4 × ½ = 2 katıdır.'),
  ('Soğukken direnci küçük olan bir tungsten flamanlı ampul, anahtar kapatıldığı ilk anda neden daha büyük akım çeker?', 'Tel soğukken direnci düşüktür, ısındıkça direnci artar', ['Telin direnci ısındıkça azalır', 'Şebeke gerilimi ilk anda geçici olarak artar', 'Ampulün içindeki gaz, ilk anda iyonlaşarak ek bir iletim yolu oluşturur'], 'Metallerde direnç sıcaklıkla artar. Soğuk flaman düşük dirençli olduğundan I = V/R ilk anda büyüktür; ısınınca direnç artar, akım düşer.'),
  ('Bakırın direncinin sıcaklıkla artmasının mikroskobik nedeni nedir?', 'Isınan örgü iyonlarının titreşimi artıp elektronların daha sık çarpışması', ['Serbest elektron sayısının azalması', 'Elektronların kütlesinin artması nedeniyle ivmelenmelerinin zorlaşması ve çarpışmaların azalması', 'Örgü iyonlarının yük kazanması'], 'Sıcaklık artınca örgü iyonlarının titreşim genliği büyür, elektronlar daha sık saçılır ve akıma gösterilen direnç artar.'),
  ('Seri bağlı iki dirençten birinin değeri diğerinin iki katıdır. Küçük olan direncin uçlarındaki gerilim 5 V ise kaynak gerilimi kaç volttur?', '15 V', ['10 V', '7,5 V', '20 V'], 'Seri devrede gerilim dirençle orantılıdır; büyük dirençte 10 V düşer. Toplam 5 + 10 = 15 V\'tur.'),
  ('6 Ω ve 12 Ω\'luk iki direnç seri olarak 18 V\'a bağlanmıştır. 12 Ω\'luk direnç 24 Ω\'luk bir dirençle değiştirilirse 6 Ω\'luk direncin harcadığı güç kaç watt olur?', '2,16 W', ['6 W', '0,216 W', '1,08 W'], 'Yeni akım I = 18/(6+24) = 0,6 A\'dir. 6 Ω\'daki güç P = I²R = 0,36 × 6 = 2,16 W\'tır (önceden 6 W idi).'),
  ('Çalışma gerilimi 2 V ve akımı 20 mA olan bir LED, 5 V\'luk kaynağa seri bir ön dirençle bağlanacaktır. Ön direnç kaç ohm olmalıdır?', '150 Ω', ['1500 Ω', '250 Ω', '15 Ω'], 'Dirençte düşmesi gereken gerilim 5 − 2 = 3 V\'tur. R = 3 V / 0,02 A = 150 Ω olur.'),
  ('2 Ω, 3 Ω ve 5 Ω\'luk dirençler seri bağlanmıştır ve toplam harcanan güç 40 W\'tır. 5 Ω\'luk direncin harcadığı güç kaç watttır?', '20 W', ['25 W', '10 W', '12,5 W'], 'Toplam direnç 10 Ω; 40 = I²·10 ise I = 2 A. 5 Ω\'daki güç P = 4 × 5 = 20 W\'tır.'),
  ('2 Ω ve 3 Ω\'luk dirençler paralel bağlanmıştır ve ana koldan 10 A akım geçmektedir. 2 Ω\'luk koldan geçen akım kaç amperdir?', '6 A', ['4 A', '5,5 A', '3 A'], 'Paralel kollarda akım dirençle ters orantılı bölünür: I₂Ω = 10 × 3/(2+3) = 6 A.'),
  ('Paralel bağlı iki özdeş lambadan biri patlarsa kalan lambanın parlaklığı ve kaynaktan çekilen toplam akım nasıl değişir? (Üretecin iç direnci ihmal edilir)', 'Parlaklık aynı kalır, toplam akım yarıya iner', ['Parlaklık artar, toplam akım yarıya iner', 'Parlaklık aynı kalır, toplam akım iki katına çıkar', 'Lamba söner, akım sıfır olur'], 'Kalan lambanın gerilimi kaynak gerilimi olarak değişmez; akımı da aynıdır. Toplam akım iki kolun toplamından tek kola, yani yarıya düşer.'),
  ('R ve 3R değerli iki direnç paralel bağlanırsa eşdeğer direnç kaç R olur?', '0,75 R', ['1,333 R', '1,5 R', '0,25 R'], 'R_eş = (R·3R)/(R+3R) = 3R²/4R = 0,75 R\'dir.'),
  ('Paralel bağlı iki dirençten biri 4 Ω\'dur ve eşdeğer direnç 2,4 Ω\'dur. Diğer direnç kaç ohmdur?', '6 Ω', ['1,6 Ω', '8 Ω', '3 Ω'], '1/R = 1/2,4 − 1/4 = 5/12 − 3/12 = 2/12 = 1/6 olduğundan R = 6 Ω\'dur.'),
  ('12 V\'luk bir kaynağa paralel bağlı 6 Ω ve 12 Ω\'luk dirençlerin harcadığı toplam güç kaç watttır?', '36 W', ['24 W', '18 W', '108 W'], 'Güçler V²/R ile bulunur: 144/6 = 24 W ve 144/12 = 12 W; toplam 36 W\'tır.'),
  ('Paralel bağlı iki koldan birindeki 3 Ω\'luk dirençten 2 A geçmektedir; ana koldan 5 A akım geçmektedir. Diğer koldaki direnç kaç ohmdur?', '2 Ω', ['3 Ω', '4,5 Ω', '1,2 Ω'], '3 Ω\'luk kolun gerilimi 6 V\'tur. Diğer koldan 3 A geçtiğinden direnci 6/3 = 2 Ω\'dur.'),
  ('Bir devrede 3 Ω\'luk direnç, birbirine paralel iki özdeş 6 Ω\'luk direnç ve 5 Ω\'luk direnç ile seri bağlıdır. Devre 22 V\'luk üretece bağlanırsa ana koldan geçen akım kaç amperdir? (İç direnç ihmal ediliyor)', '2 A', ['1,1 A', '4 A', '2,5 A'], 'Paralel kısım 3 Ω\'dur; toplam direnç 3 + 3 + 5 = 11 Ω. I = 22/11 = 2 A bulunur.'),
  ('10 Ω, 20 Ω ve 30 Ω\'luk dirençler seri bağlanmıştır. 20 Ω\'luk direncin iki ucu iletken telle birleştirilip devre 60 V\'a bağlanırsa devreden geçen akım kaç amper olur?', '1,5 A', ['1 A', '3 A', '0,75 A'], '20 Ω kısa devre edilince etkisiz kalır. Toplam direnç 10 + 30 = 40 Ω; I = 60/40 = 1,5 A\'dir.'),
  ('12 V\'luk bir kaynağa 2 Ω\'luk bir direnç, 4 Ω\'luk R₂ direnci ile seri bağlıdır. Anahtar K kapatıldığında R₂\'ye paralel 4 Ω\'luk bir R₃ direnci devreye girmektedir. K kapatıldığında ana koldaki akım kaç amper artar?', '1 A', ['2 A', '0,5 A', '3 A'], 'K açıkken I = 12/6 = 2 A\'dir. K kapalıyken R₂ ‖ R₃ = 2 Ω olur, toplam 4 Ω ve I = 3 A\'dir. Artış 1 A\'dir.'),
  ('Toplam direnci 16 Ω olan düzgün, ince bir tel halka, bir çapının iki ucundan devreye bağlanıyor. Bu iki nokta arasındaki eşdeğer direnç kaç ohmdur?', '4 Ω', ['8 Ω', '16 Ω', '2 Ω'], 'Çap halkayı iki yarım çembere böler; her biri 8 Ω\'dur ve paralel bağlıdır: 8/2 = 4 Ω.'),
  ('Toplam direnci 16 Ω olan düzgün tel halkanın üzerinde, aralarında çeyrek çember yay bulunan iki noktadan devreye bağlantı yapılıyor. Bu iki nokta arasındaki eşdeğer direnç kaç ohmdur?', '3 Ω', ['4 Ω', '12 Ω', '2,4 Ω'], 'Çeyrek yayın direnci 4 Ω, kalan yay 12 Ω\'dur ve ikisi paralel bağlıdır: (4·12)/(4+12) = 3 Ω.'),
  ('Metre köprüsü deneyinde bilinmeyen X direnci sol aralığa, 6 Ω\'luk standart direnç sağ aralığa konmuştur. Galvanometre, telin sol ucundan 40 cm uzaktaki noktada sıfır gösterdiğine göre X kaç ohmdur?', '4 Ω', ['9 Ω', '2,4 Ω', '6 Ω'], 'Denge koşulu X/6 = l₁/l₂ = 40/60\'tır. Buradan X = 4 Ω bulunur.'),
  ('Bir üretece özdeş L₁, L₂ ve L₃ lambaları bağlanmıştır: L₂ ile L₃ birbirine paralel, bu grup ise L₁ ile seri bağlıdır. Lambaların parlaklıkları için hangisi doğrudur?', 'L₁ en parlaktır, L₂ ile L₃ eşit ve daha sönüktür', ['L₁, L₂ ve L₃ eşit parlaklıktadır', 'L₂ ile L₃, L₁\'den daha parlaktır, çünkü akımları daha büyüktür', 'L₂ L₃\'ten parlaktır'], 'L₁\'den toplam akım, L₂ ve L₃\'ten ise bunun yarısı geçer. P = I²R olduğundan P₁ = 4P₂ = 4P₃\'tür.'),
  ('Bir batarya 18 V sağlıyor. Pilin ucuna önce 3 Ω\'luk bir rezistans, ardından iki paralel kol (6 Ω ve 3 Ω) takılmış. Yalnız 6 Ω\'luk koldaki akım nedir?', '1,2 A', ['3,6 A', '2,4 A', '0,36 A'], 'Paralel grup 2 Ω; toplam 5 Ω; ana akım 3,6 A\'dir. Gruptaki gerilim 3,6 × 2 = 7,2 V; 6 Ω\'dan 7,2/6 = 1,2 A geçer.'),
  ('Elinde yalnızca 4 Ω\'luk özdeş dirençler bulunan bir öğrenci 6 Ω\'luk eşdeğer direnç elde etmek istiyor. En az kaç direnç kullanması gerekir?', '3', ['2', '4', '6'], 'İki direnç paralel bağlanıp 2 Ω elde edilir; buna bir direnç seri eklenince 6 Ω olur. Toplam 3 direnç yeterlidir.'),
  ('Bir devrede 4 Ω\'luk direnç ile 12 Ω\'luk direnç paralel, bu grup 5 Ω\'luk dirençle seri bağlıdır. A–B uçları arasına 16 V uygulanırsa 5 Ω\'luk direncin harcadığı güç kaç watt olur?', '20 W', ['16 W', '32 W', '12,8 W'], 'Toplam direnç 3 + 5 = 8 Ω, akım 2 A\'dir. 5 Ω\'da P = I²R = 4 × 5 = 20 W olur.'),
  ('Bir devrede 2 Ω\'luk direnç, 6 Ω ve 3 Ω\'luk paralel dirençlerle seri bağlıdır; ayrıca bu tüm düzen 3 Ω\'luk bir dirence daha paraleldir. Eşdeğer direnç kaç ohmdur?', '12/7 Ω ≈ 1,71 Ω', ['4 Ω', '1,5 Ω', '12/5 Ω ≈ 2,4 Ω'], '6 ‖ 3 = 2 Ω; bununla 2 Ω seri olunca 4 Ω olur. Bu 4 Ω, 3 Ω ile paraleldir: (4·3)/(4+3) = 12/7 ≈ 1,71 Ω.'),
  ('Emk\'sı 12 V, iç direnci 0,02 Ω olan bir akü, marş motoruna kısa süre 150 A akım vermektedir. Bu sırada akünün uç gerilimi kaç volttur?', '9 V', ['12 V', '11,7 V', '3 V'], 'İç dirençte düşen gerilim 150 × 0,02 = 3 V\'tur. Uç gerilimi 12 − 3 = 9 V olur; far lambalarının soluklaşması bu yüzden görülür.'),
  ('Emk\'sı 10 V, iç direnci 2 Ω olan bir üretecin uç gerilimi 8 V ölçülüyor. Üretece bağlı dış direnç kaç ohmdur?', '8 Ω', ['4 Ω', '5 Ω', '10 Ω'], 'İç dirençte 2 V düşmüştür, akım I = 2/2 = 1 A\'dir. Dış direnç R = V/I = 8/1 = 8 Ω\'dur.'),
  ('Emk\'sı 6 V, iç direnci 1 Ω olan bir üreteç 2 Ω\'luk bir dirence bağlanıyor. Üretecin iç direncinde harcanan güç kaç watttır?', '4 W', ['8 W', '12 W', '2 W'], 'Akım I = 6/(2+1) = 2 A\'dir. İç dirençteki güç P = I²r = 4 × 1 = 4 W olur.'),
  ('Bir üretecin emk\'sı 10 V, iç direnci 1 Ω\'dur ve dış direnç 9 Ω\'dur. Üretecin verimi (uç gerilimi/emk) yüzde kaçtır?', '%90', ['%11,1', '%81', '%99'], 'Akım 1 A\'dir, uç gerilimi 9 V\'tur. Verim 9/10 = %90\'dır; ayrıca η = R/(R + r) = 9/10 bağıntısıyla da bulunur.'),
  ('Her birinin emk\'sı 1,5 V ve iç direnci 0,6 Ω olan üç özdeş pil paralel bağlanıyor. Bu bileşimin eşdeğer iç direnci kaç ohmdur?', '0,2 Ω', ['1,8 Ω', '0,6 Ω', '0,18 Ω'], 'Özdeş üreteçler paralel bağlanınca emk değişmez, iç direnç r/3 = 0,6/3 = 0,2 Ω olur.'),
  ('Her biri 1,5 V emk\'lı ve 0,5 Ω iç dirençli üç pil seri bağlanıp 1,5 Ω\'luk dirence bağlanıyor. Devreden geçen akım kaç amperdir?', '1,5 A', ['3 A', '0,75 A', '2,25 A'], 'Toplam emk 4,5 V, toplam direnç 1,5 + 1,5 = 3 Ω\'dur. I = 4,5/3 = 1,5 A bulunur.'),
  ('Bir üretecin uç gerilimi, çekilen akım 0 A iken 12 V, 4 A iken 8 V ölçülüyor. Üretecin iç direnci kaç ohmdur?', '1 Ω', ['2 Ω', '0,5 Ω', '4 Ω'], 'Yüksüz uç gerilimi emk\'ya eşittir (12 V). Gerilim düşüşü 4 V ve akım 4 A olduğundan r = 4/4 = 1 Ω\'dur.'),
  ('Emk\'sı 12 V ve iç direnci 3 Ω olan bir üreteçten, dış direnç en uygun değerde seçilirse dış devreye aktarılabilecek en büyük güç kaç watttır?', '12 W', ['144 W', '24 W', '6 W'], 'En büyük güç R = r = 3 Ω iken elde edilir: P = ε²/(4r) = 144/12 = 12 W\'tır.'),
  ('Emk\'sı 24 V, iç direnci 2 Ω olan bir üretece 8 Ω\'luk bir direnç bağlandığında dış dirençte harcanan güç kaç watttır?', '46,08 W', ['72 W', '57,6 W', '460,8 W'], 'Akım I = 24/(8+2) = 2,4 A\'dir. Dış dirençte P = I²R = 5,76 × 8 = 46,08 W olur.'),
  ('Her biri 2 V emk\'lı ve 0,5 Ω iç dirençli üç pil seri bağlanıp 4,5 Ω\'luk dirence bağlanıyor. Pillerden birinin uçları arasındaki gerilim kaç volttur?', '1,5 V', ['2 V', '1,25 V', '0,5 V'], 'Toplam emk 6 V, toplam direnç 4,5 + 1,5 = 6 Ω; I = 1 A. Bir pilin uç gerilimi 2 − 1 × 0,5 = 1,5 V\'tur.'),
  ('12 V ve 60 Ah değerlerine sahip bir araç aküsü, 60 W\'lık bir lambayı (verim kayıpları ihmal) en çok kaç saat yakabilir?', '12 saat', ['5 saat', '60 saat', '0,083 saat'], 'Depolanan enerji 12 × 60 = 720 Wh\'tır. Süre = 720 Wh / 60 W = 12 saattir.'),
  ('Tek ilmekli devrede 20 V ve 6 V\'luk iki ideal pil birbirine zıt yönde, 2 Ω, 3 Ω ve 5 Ω\'luk dirençlerle seri bağlıdır. Devreden geçen akım kaç amperdir?', '1,4 A', ['2,6 A', '2 A', '0,14 A'], 'Net emk 20 − 6 = 14 V, toplam direnç 10 Ω\'dur. I = 14/10 = 1,4 A olur.'),
  ('Bir devrede yük korunumunun düğüm kuralına ve enerji korunumunun ilmek kuralına yol açtığını bilen bir öğrenci, düğümde akım toplamının sıfırdan farklı çıktığı bir hesap yapıyor. Bu durum neyin işaretidir?', 'Hesapta ya da akım yönlerinde bir hata yapıldığının', ['Yükün düğümde biriktiği ve devrenin kararlı olmadığının', 'Enerjinin yok olduğunun', 'Direncin negatif olduğunun'], 'Kararlı bir devrede düğümde yük birikemez; toplamın sıfırdan farklı çıkması hesap ya da yön hatası demektir.'),
  ('9 V\'luk ideal bir kaynağa 8 Ω\'luk bir direnç bağlıdır. Devreye seri bağlanan ve iç direnci 1 Ω olan bir ampermetre kaç amper gösterir?', '1 A', ['1,125 A', '0,9 A', '9 A'], 'Ampermetrenin iç direnci toplam direnci 9 Ω yapar: I = 9/9 = 1 A. Ampermetre olmasaydı akım 1,125 A olurdu.'),
  ('Bir direnci omik olarak ölçerken multimetreyi direnç konumuna alıp uçlarını devreye bağlamadan önce devrenin enerjisinin kesilmesi gerekir. Bunun nedeni nedir?', 'Alet kendi iç pilinden akım gönderir, dış kaynak ölçümü bozar ve aleti bozabilir', ['Dirençler enerjili iken ısınıp değerini kalıcı olarak kaybeder ve alet hata verir', 'Ohm yasası yalnızca enerjisiz devrelerde geçerlidir', 'Alet yalnızca alternatif akımda çalışır'], 'Ohmmetre ölçümünde alet kendi pilini kullanır; devrede başka bir kaynak varsa ölçüm hatalı olur ve aletin devresi zarar görebilir.'),
  ('Tam ölçek akımı 1 mA ve iç direnci 100 Ω olan bir galvanometre, 0–10 V\'luk voltmetreye dönüştürülmek isteniyor. Seri bağlanacak çarpan direnç kaç ohm olmalıdır?', '9900 Ω', ['10 000 Ω', '9000 Ω', '99 Ω'], 'Toplam direnç 10 V / 0,001 A = 10 000 Ω olmalıdır. Çarpan direnç 10 000 − 100 = 9900 Ω\'dur.'),
  ('Bir voltmetrenin ölçme sınırı 5 katına çıkarılmak isteniyor. Voltmetreye seri bağlanacak direnç, voltmetrenin iç direncinin kaç katı olmalıdır?', '4 katı', ['5 katı', '1/5 katı', '1/4 katı'], 'Aynı akımda toplam gerilim 5 kat olacağından toplam direnç 5R olmalıdır; eklenen seri direnç 4R\'dir.'),
  ('Bir ampermetrenin ölçme sınırı 10 katına çıkarılacaktır. Ampermetrenin iç direnci R ise paralel bağlanacak şönt direnç kaç R olmalıdır?', 'R/9', ['9R', 'R/10', '10R'], 'Akımın 1/10\'u alet kolundan, 9/10\'u şönttten geçmelidir. Paralel kollarda akım dirençle ters orantılı olduğundan Rş = R/9\'dur.'),
  ('Üzerinde 6 V – 3 W yazan bir lamba 9 V\'luk bir bataryayla normal parlaklıkta yakılmak isteniyor. Lambaya seri bağlanacak direnç kaç ohm olmalıdır?', '6 Ω', ['3 Ω', '12 Ω', '2 Ω'], 'Lamba akımı I = 3/6 = 0,5 A\'dir. Dirençte 3 V düşmelidir: R = 3/0,5 = 6 Ω.'),
  ('Akkor lamba elektrik gücünün yaklaşık %5\'ini, LED lamba ise %20\'sini ışığa çevirir. 100 W\'lık bir akkor lambayla aynı ışık gücünü veren LED lambanın elektrik gücü kaç watt olur?', '25 W', ['12,5 W', '20 W', '50 W'], 'Akkor lambanın ışık gücü 100 × 0,05 = 5 W\'tır. LED için 5/0,20 = 25 W elektrik gücü yeterlidir.'),
  ('Üç özdeş lambadan K ile L birbirine seri, M ise bu seri koluna paralel bağlanmış ve devre bir kaynağa takılmıştır. M lambasının gücü K lambasının gücünün kaç katıdır?', '4 katı', ['2 katı', 'Yarısı', 'Eşit olur'], 'K ile L eşit gerilim paylaşır; her birinde V/2 vardır, M\'de ise V. P = V²/R olduğundan M\'nin gücü K\'nınkinin 4 katıdır.'),
  ('Gücü 150 W olan bir buzdolabının kompresörü günde ortalama 8 saat çalışmaktadır. 30 günde tüketilen elektrik enerjisi kaç kWh\'tir?', '36 kWh', ['3,6 kWh', '108 kWh', '144 kWh'], 'Günlük enerji 0,15 kW × 8 h = 1,2 kWh\'tir. 30 günde 36 kWh tüketilir.'),
  ('Bekleme (stand-by) modunda sürekli 5 W güç çeken bir cihaz, bir yıl (365 gün) prizde bırakılırsa yaklaşık kaç kWh enerji harcar?', '43,8 kWh', ['1,8 kWh', '43 800 kWh', '120 kWh'], 'Enerji 5 W × 24 h × 365 = 43 800 Wh = 43,8 kWh\'tir.'),
  ('Gücü 1800 W olan bir elektrik süpürgesi yarım saat çalışıyor. Harcanan enerji kaç joule\'dür?', '3,24 × 10⁶ J', ['1,8 × 10⁶ J', '5,832 × 10⁶ J', '3,24 × 10³ J'], 'Enerji 1800 W × 1800 s = 3,24×10⁶ J\'dür; bu 0,9 kWh\'e karşılık gelir.'),
  ('Günde 5 saat yanan 60 W\'lık bir akkor lamba yerine 9 W\'lık bir LED lamba takılırsa bir yılda (365 gün) yaklaşık kaç kWh enerji tasarruf edilir?', '93 kWh', ['9,3 kWh', '55 kWh', '930 kWh'], 'Güç farkı 51 W\'tır. Enerji farkı 0,051 kW × 5 h × 365 ≈ 93 kWh\'tir.'),
  ('Gücü 1000 W olan bir elektrikli ısıtıcı, 1 kg suyu 20 °C\'den 80 °C\'ye ısıtıyor. Isı kaybı yoksa gereken süre kaç saniyedir? (c = 4200 J/kg·°C)', '252 s', ['60 s', '420 s', '25,2 s'], 'Gereken ısı Q = 1 × 4200 × 60 = 252 000 J\'dür. Süre t = Q/P = 252 000/1000 = 252 s\'dir.'),
  ('3 Ω ve 6 Ω\'luk iki direnç paralel bağlanıp 12 V\'a bağlanıyor. Bu iki direncin 5 saniyede açığa çıkardığı toplam ısı kaç joule\'dür?', '360 J', ['180 J', '1440 J', '720 J'], 'Güçler 144/3 = 48 W ve 144/6 = 24 W\'tır; toplam 72 W. Isı Q = 72 × 5 = 360 J olur.'),
  ('Kısa devre durumunda kablolarda yangın riskinin artmasının nedeni Joule yasasına göre nedir?', 'Isı akımın karesiyle orantılı olduğundan akım büyüdükçe ısı çok hızlı artar', ['Isı akımla ters orantılı olduğundan kablo soğur', 'Isı yalnız gerilime bağlı olduğundan kısa devrede gerilim çok artar ve kablo erir', 'Direnç kısa devrede sonsuz olur'], 'Joule ısısı Q = I²Rt\'dir; kısa devrede akım çok büyür ve ısı akımın karesi kadar arttığından kablolar aşırı ısınır.'),
  ('12 μF ve 4 μF\'lık iki kondansatör seri bağlanıp 16 V\'luk üretece bağlanıyor. Her bir kondansatörün levhalarında biriken yük kaç μC\'dir?', '48 μC', ['64 μC', '192 μC', '12 μC'], 'Eşdeğer sığa (12·4)/(12+4) = 3 μF\'tır. Seri bağlamada yük her kondansatörde aynıdır: q = 3 × 16 = 48 μC.'),
  ('10 V\'a kadar yüklenmiş 6 μF\'lık bir kondansatör, yüksüz 3 μF\'lık bir kondansatöre paralel bağlanıyor. Ortak gerilim yaklaşık kaç volt olur?', '6,67 V', ['10 V', '5 V', '13,33 V'], 'Toplam yük 60 μC korunur. Ortak gerilim V = 60/(6+3) = 6,67 V\'tur.'),
  ('Sığası 100 μF olan bir kondansatör 9 V\'a kadar yüklendiğinde depoladığı enerji kaç milijouledir?', '4,05 mJ', ['0,45 mJ', '0,405 mJ', '40,5 mJ'], 'U = ½CV² = 0,5 × 100×10⁻⁶ × 81 = 4,05×10⁻³ J = 4,05 mJ\'dir.'),
  ('Kalp defibrilatöründeki 70 μF\'lık kondansatör 5000 V\'a yüklenirse depoladığı enerji kaç joule\'dür?', '875 J', ['175 J', '1750 J', '350 J'], 'U = ½CV² = 0,5 × 70×10⁻⁶ × 25×10⁶ = 875 J\'dür.'),
  ('Bir fotoğraf flaşındaki 1000 μF\'lık kondansatör 300 V\'a yüklenmişse depolanan enerji kaç joule\'dür?', '45 J', ['4,5 J', '90 J', '450 J'], 'U = ½CV² = 0,5 × 10⁻³ × 9×10⁴ = 45 J\'dür.'),
  ('Bir RC devresinde kondansatör üreteçten dolarken 2τ süre sonunda yük, son değerinin yaklaşık yüzde kaçına ulaşır? (e⁻² ≈ 0,135)', '%86', ['%63', '%99,5', '%74'], 'Dolma sırasında q = q₀(1 − e^(−t/τ)) olduğundan t = 2τ için q ≈ q₀(1 − 0,135) ≈ 0,865 q₀ yani yaklaşık %86\'dır.'),
  ('Başlangıçta boşalmış bir kondansatör 12 V\'luk bir üreteçle 4 kΩ\'luk dirençten dolmaya başlıyor. Anahtar kapatıldığı andaki akım kaç miliamperdir?', '3 mA', ['0 mA', '48 mA', '0,33 mA'], 'Boş kondansatör ilk anda kısa devre gibi davranır; akım I = ε/R = 12/4000 = 3 mA\'dir.'),
  ('Her biri 100 V\'a dayanıklı iki özdeş kondansatör seri bağlanıyor. Bu bileşim en fazla kaç volt uygulanabilir? (Her ikisi de aynı sığada)', '200 V', ['100 V', '50 V', '1000 V'], 'Özdeş seri kondansatörlerde gerilim eşit paylaşılır; her biri 100 V\'a dayandığından toplam 200 V\'a kadar güvenle çıkılır.'),
  ('Dayanma gerilimi 50 V olan bir kondansatör ile dayanma gerilimi 100 V olan bir kondansatör paralel bağlanıyor. Bileşime en fazla kaç volt uygulanabilir?', '50 V', ['100 V', '150 V', '75 V'], 'Paralel kollarda gerilim aynıdır; aşılmaması gereken sınır dayanıklılığı daha düşük olan kondansatörün 50 V\'udur.'),
  ('Havanın dielektrik dayanımı yaklaşık 3 × 10⁶ V/m\'dir. Levhalar arası 1 mm olan hava dolu bir kondansatörde hava delinmeden uygulanabilecek en büyük gerilim yaklaşık kaç volttur?', '3000 V', ['3 V', '3 × 10⁹ V', '300 V'], 'V = E·d = 3×10⁶ × 1×10⁻³ = 3000 V\'tur; bu değerden sonra levhalar arasında kıvılcım atlar.'),
  ('Elektrolitik bir kondansatör devreye ters kutuplu bağlanırsa ne olması beklenir?', 'Yalıtkan oksit tabakası bozulur, aşırı ısınıp patlayabilir', ['Sığası iki katına çıkar', 'Daha verimli çalışır', 'Yalnızca alternatif akım geçirir ve doğru akımı tamamen keser'], 'Elektrolitik kondansatörlerin kutupları vardır; ters bağlanınca oksit katman bozulur, kaçak akım artar ve kondansatör şişip patlayabilir.'),
  ('2 μF ve 4 μF\'lık iki kondansatör paralel bağlanmış, bu grup 6 μF\'lık üçüncü kondansatörle seri bağlanmıştır. Eşdeğer sığa kaç μF\'tır?', '3 μF', ['12 μF', '1,2 μF', '6 μF'], 'Paralel grup 2 + 4 = 6 μF\'tır. Bu, 6 μF ile seri olunca (6·6)/(6+6) = 3 μF olur.'),
  ('10 A\'lik bir sigortayla korunan bir hatta 220 V\'ta aynı anda 1500 W, 1000 W ve 800 W\'lık üç cihaz çalıştırılırsa sigorta için ne söylenebilir?', 'Toplam akım yaklaşık 15 A olacağından sigorta atar', ['Toplam akım yaklaşık 10 A olduğundan sigorta sınırda kalır ve atmaz', 'Toplam akım 3,3 A olduğundan sigorta atmaz', 'Toplam akım 33 A olur ve kablo hemen yanar'], 'Toplam güç 3300 W\'tır; I = 3300/220 = 15 A olur. Bu değer 10 A\'lik sigortanın sınırını aştığından sigorta atar.'),
  ('Bir aydınlatma devresinde anahtarın, lambanın nötr iletkenine değil faz iletkenine bağlanmasının nedeni nedir?', 'Anahtar açıkken lamba yuvasında gerilim bulunmasın ve elektrik çarpma riski azalsın', ['Lamba daha parlak yansın ve devrenin toplam direnci azalsın diye, anahtarın yeri ölçüme etki eder', 'Nötr iletkeni akımı geçirmediği için', 'Telin daha ince seçilebilmesi ve maliyetin düşmesi için'], 'Anahtar fazı kestiğinde lamba yuvası ve ampul uçları gerilimsiz kalır; ampul değişirken çarpılma tehlikesi ortadan kalkar.'),
  ('Vücut direncinin ıslak ciltte yaklaşık 1 kΩ\'a düştüğü bir kişi 220 V\'luk iletkene dokunursa vücuttan geçecek akım kaç miliamper olur?', '220 mA', ['0,22 mA', '2,2 mA', '22 mA'], 'I = V/R = 220/1000 = 0,22 A = 220 mA\'dir. Bu değer insan için ölümcül olabilecek büyüklüktedir; kuru elle bu akım çok daha küçüktür.'),
  ('5 V\'luk bir kaynağa 430 Ω\'luk bir direnç ve ileri yönde bağlanmış, eşik gerilimi 0,7 V olan silisyum diyot seri bağlanmıştır. Devreden geçen akım kaç miliamperdir?', '10 mA', ['11,6 mA', '7 mA', '1 mA'], 'Dirençte düşen gerilim 5 − 0,7 = 4,3 V\'tur. I = 4,3/430 = 0,01 A = 10 mA olur.'),
  ('Ters yönde bağlanmış ideal bir diyot, 9 V\'luk kaynak ve 1 kΩ\'luk direnç seri bağlıdır. Dirençten geçen akım ve diyodun uçlarındaki gerilim nedir?', 'Akım yok denecek kadar küçük; gerilimin tamamı diyotta düşer', ['9 mA akım geçer ve gerilimin tamamı dirençte düşer', '4,5 mA; gerilim eşit paylaşılır', 'Akım sonsuz olur; diyot kısa devre gibi davranır ve gerilimin tamamı dirençte kalır'], 'Ters yönde ideal diyot açık devre gibidir. Akım sıfır olduğundan dirençte gerilim düşmez ve 9 V diyotta görünür.'),
  ('Her biri 0,7 V eşik gerilimli iki silisyum diyot ileri yönde seri bağlanıp 760 Ω\'luk dirençle birlikte 9 V\'a bağlanıyor. Devreden geçen akım kaç miliamperdir?', '10 mA', ['11,8 mA', '9,2 mA', '12 mA'], 'Diyotlarda toplam 1,4 V düşer. Dirençte 9 − 1,4 = 7,6 V kalır; I = 7,6/760 = 10 mA\'dir.'),
  ('10 kW\'lık elektriksel güç 200 V\'ta, direnci 0,5 Ω olan bir hat üzerinden iletiliyor. Hatta ısıya dönüşen güç kaç watttır?', '1250 W', ['25 W', '12 500 W', '5000 W'], 'Hat akımı I = P/V = 10 000/200 = 50 A\'dir. Kayıp Pkayıp = I²R = 2500 × 0,5 = 1250 W\'tır.'),
  ('Aynı güç, aynı hat üzerinden gerilim 10 katına çıkarılarak iletilirse hattaki ısı kaybı ilk değerin kaç katına düşer?', '1/100', ['1/10', '1/20', '1/1000'], 'P sabitken I = P/V olduğundan akım 1/10\'a iner. Kayıp I²R ile orantılı olduğundan 1/100\'e düşer.'),
  ('Özdirenci 2,8 × 10⁻⁸ Ω·m, kesit alanı 4 cm² olan alüminyum bir iletken hattın uzunluğu 100 km\'dir. Hattın direnci kaç ohmdur?', '7 Ω', ['0,7 Ω', '70 Ω', '2,8 Ω'], 'R = ρL/A = 2,8×10⁻⁸ × 10⁵ / (4×10⁻⁴) = 7 Ω\'dur. Alanı m²\'ye (4×10⁻⁴), uzunluğu metreye çevirmek gerekir.'),
  ('12 V\'luk bir kaynağa 6 Ω\'luk bir lamba ile 0–6 Ω aralığında ayarlanabilen bir reosta seri bağlanmıştır. Devreden geçebilecek en küçük akım kaç amperdir?', '1 A', ['2 A', '0,5 A', '1,5 A'], 'Reosta en büyük değerindeyken toplam direnç 12 Ω\'dur; en küçük akım 12/12 = 1 A olur. Reosta sıfırdayken akım 2 A\'e çıkar.'),
  ('Yüzey alanı 1,6 m² olan, verimi %20 olan bir güneş paneline 1000 W/m² şiddetinde ışık dik düşüyor. Panelin elektriksel çıkış gücü kaç watttır?', '320 W', ['1600 W', '200 W', '32 W'], 'Panele ulaşan ışık gücü 1,6 × 1000 = 1600 W\'tır; %20\'si elektriğe dönüşür: 1600 × 0,20 = 320 W.'),
  ('Çıkışı 5 V ve 2 A olan bir şarj adaptörü şebekeden 12,5 W güç çekmektedir. Adaptörün verimi yüzde kaçtır?', '%80', ['%125', '%62,5', '%20'], 'Çıkış gücü 5 × 2 = 10 W\'tır. Verim 10/12,5 = 0,8 yani %80\'dir; geri kalan 2,5 W ısıya dönüşür.'),
  ('220 V\'luk şebekede 1000 W güç veren bir ısıtıcıda iki özdeş rezistans kullanılmaktadır. Rezistanslar paralel bağlanırsa ısıtıcının gücü kaç watt olur? (Her biri tek başına 1000 W veriyor)', '2000 W', ['500 W', '1000 W', '20 000 W'], 'Paralel bağlamada her rezistans tam gerilim altında 1000 W harcar; toplam 2000 W olur.'),
  ('220 V\'luk şebekede, 44 Ω ve 88 Ω\'luk iki rezistansı olan bir ısıtıcı rezistansların paralel bağlanmasıyla çalıştırılıyor. Toplam güç kaç watttır?', '1650 W', ['1100 W', '550 W', '16 500 W'], 'Güçler 220²/44 = 1100 W ve 220²/88 = 550 W\'tır. Paralelde toplam 1650 W olur.'),
  ('\'Pil devreden akım tüketir\' ifadesi bilimsel açıdan neden yanlıştır?', 'Akım devrede tükenmez; pilin kimyasal enerjisi başka enerjilere dönüşür', ['Pil aslında hazır yük depolar; devreden geçen yük zamanla azalarak sonunda sıfırlanır', 'Akım yalnızca dirençlerde yok olur', 'Akım ışık hızında kaybolur'], 'Akım yük akışıdır ve devrenin her kesitinde aynıdır, yük tükenmez. Tükenen şey yüklerin taşıdığı enerjidir; bu enerji direnç, lamba gibi elemanlarda dönüşür.'),
  ('36 V ve 10 Ah değerlerinde bataryası bulunan bir elektrikli bisiklet, ortalama 250 W güç çekerse bataryayla yaklaşık kaç saat gider?', '1,44 saat', ['0,69 saat', '14,4 saat', '0,0069 saat'], 'Batarya enerjisi 36 × 10 = 360 Wh\'tır. Süre = 360/250 = 1,44 saattir.'),
  ('Bir elektrikli ısıtıcı rezistansının neredeyse %100 verimli sayılmasının nedeni nedir?', 'Harcanan elektrik enerjisinin hemen hemen tamamı ısıya dönüşür', ['Rezistans enerji üretir', 'Isı ortamdan çekildiği için', 'Gerilim ısıtıcı içinde yükseltilir ve enerji böylece çoğalır, verim %100 üstüne çıkar'], 'Rezistansta elektrik enerjisinin tamamı Joule ısısına dönüşür; ısıtma amacıyla kullanıldığında kayıp yok denecek kadar azdır.'),
  ('Elektriksel yük biriminin (coulomb) adını aldığı Fransız bilim insanı hangi cihazla yükler arasındaki kuvveti ölçmüştür?', 'Burulma terazisi', ['Galvanometre', 'Hassas elektronik osiloskop', 'Termometre'], 'Charles-Augustin de Coulomb, yükler arası kuvveti burulma terazisiyle ölçerek ters kare yasasını ortaya koymuştur; yük birimi onun adını taşır.'),
  ('19. yüzyıl sonundaki \'akımlar savaşı\'nda alternatif akımın, doğru akıma göre uzun mesafe elektrik iletiminde üstün sayılmasının temel nedeni nedir?', 'Transformatörle gerilimin kolayca yükseltilip hat kaybının azaltılabilmesi', ['Alternatif akımın hiç ısı kaybı yaratmaması', 'Alternatif akımda akımın iletkenin içinde ilerlememesi', 'Alternatif akımın küçük pillerle kolayca üretilip taşınabilmesi ve ucuz olması'], 'Alternatif gerilim transformatörle kolayca yükseltilip düşürülür; yüksek gerilimde akım azaldığı için hat kayıpları (I²R) küçülür. O dönemde doğru akım için bu kolaylık yoktu.'),
  ('1 mAh kapasite kaç coulomb yüke eşdeğerdir?', '3,6 C', ['0,36 C', '36 C', '3600 C'], '1 mAh = 10⁻³ A × 3600 s = 3,6 C\'dir.'),
  ('1 V·A·s çarpımı hangi büyüklüğün birimine eşittir?', 'Joule (enerji)', ['Watt (güç, saniye başına enerji)', 'Coulomb (yük)', 'Farad (sığa)'], 'V·A güç birimi olan watttır; watt ile saniye çarpımı enerjidir: 1 W·s = 1 J.'),
  ('Kaynağa seri bağlı sabit bir R₁ direnci ve bir reosta bulunmaktadır. Voltmetre reostaya paralel, ampermetre seri bağlıdır. Reostanın direnci artırılırsa ölçü aletleri nasıl değişir?', 'Ampermetre azalır, voltmetre artar', ['Ampermetre artar, voltmetre azalır, çünkü toplam direnç düşer', 'Her ikisi de artar', 'Her ikisi de azalır'], 'Toplam direnç arttığı için akım azalır. Sabit R₁\'deki gerilim düşüşü küçülür, kaynak gerilimi sabit olduğundan reostanın uçlarındaki gerilim artar.'),
  ('İç direnci küçük olmayan bir pile paralel özdeş lambalar birer birer eklendikçe her lambanın parlaklığı neden azalır?', 'Toplam akım artar, iç dirençte düşen gerilim büyür, uç gerilimi azalır', ['Lambaların dirençleri paralel eklendikçe artar ve akım her lambada bölünerek azalır', 'Pilin emk\'sı lamba sayısıyla düşer', 'Paralel kollarda akım hiç geçmez'], 'Paralel lamba eklemek toplam akımı artırır; I·r kaybı büyüdüğü için lambaların uçlarındaki gerilim azalır ve parlaklık düşer.'),
  ('Evde büyük bir elektrikli cihaz çalışmaya başlarken diğer lambaların bir an için kısılmasının başlıca nedeni nedir?', 'Büyük akım hat ve kaynak direncinde gerilim düşümüne yol açar', ['Lambalar seri bağlıdır ve bu yüzden gerilim cihaz sayısıyla bölünür', 'Şebekenin frekansı değişir', 'Lambaların dirençleri sıfıra iner'], 'Cihaz büyük akım çekince hat ve şebekenin iç direncinde I·R gerilim düşümü artar; lambalara ulaşan gerilim kısa süre azalır.'),
  ('Uzunluğu 30 m olan bir uzatma kablosunun gidiş-dönüş toplam direnci 0,3 Ω\'dur. Kabloya 220 V\'ta 2 kW\'lık bir cihaz bağlanırsa kablo üzerindeki gerilim düşümü yaklaşık kaç volttur?', '2,7 V', ['0,27 V', '27 V', '220 V'], 'Cihaz akımı yaklaşık 2000/220 ≈ 9,1 A\'dir. Kablodaki gerilim düşümü 9,1 × 0,3 ≈ 2,7 V olur.'),
  ('Akkor lambanın akım–gerilim ilişkisinin doğrusal olmamasının temel nedeni nedir?', 'Flaman ısındıkça direncinin artması', ['Flamanın kütlesinin artması', 'Lambanın içindeki gazın akımı sıfırlaması', 'Gerilimin sürekli değişmesi'], 'Gerilim arttıkça akım artar, flaman ısınır ve direnci yükselir; bu yüzden V/I oranı sabit kalmaz ve ilişki doğrusal olmaz.'),
  ('Paralel bağlı 5 Ω ve 20 Ω\'luk dirençlerden oluşan devreden ana koldan 10 A akım geçmektedir. Devrenin harcadığı toplam güç kaç watttır?', '400 W', ['200 W', '1000 W', '100 W'], 'Eşdeğer direnç 4 Ω\'dur. Toplam güç P = I²R = 100 × 4 = 400 W\'tır.'),
  ('Bir devrede iki özdeş lamba paralel bağlanmıştır. Lambalardan birine seri bir direnç eklenirse bu lambanın ve diğer lambanın parlaklığı nasıl değişir? (Üreteç ideal)', 'Direnç eklenen lamba sönükleşir, diğerinin parlaklığı değişmez', ['İkisi de sönükleşir', 'İkisi de parlaklaşır, çünkü toplam direnç azalır', 'Direnç eklenen lamba parlaklaşır, diğeri ise belirgin biçimde sönükleşir'], 'İdeal üretecin paralel kollarının gerilimi sabittir. Direnç eklenen kolun akımı azalır, öteki kol etkilenmez.'),
  ('4 Ω\'luk bir direnç, iki ucu iletken telle birleştirilmiş 6 Ω\'luk bir dirençle seri bağlanıp 20 V\'a bağlanıyor. Devreden geçen akım kaç amperdir?', '5 A', ['2 A', '3,33 A', '10 A'], 'Telle birleştirilen 6 Ω kısa devre edilmiştir; yalnız 4 Ω etkindir. I = 20/4 = 5 A\'dir.'),
  ('2 Ω\'luk bir direncin uçları arasındaki gerilim 6 V iken aynı direnç 3 Ω\'luk bir dirençle seri bağlanıp aynı toplam akımla çalıştırılırsa kaynak gerilimi kaç volt olmalıdır?', '15 V', ['9 V', '7,5 V', '30 V'], '2 Ω\'dan 6/2 = 3 A geçer. Toplam direnç 5 Ω olduğundan kaynak gerilimi 3 × 5 = 15 V olmalıdır.'),
  ('Özdeş dört direnç paralel bağlandığında eşdeğer direnç 5 Ω olmaktadır. Aynı dört direnç seri bağlanırsa eşdeğer direnç kaç ohm olur?', '80 Ω', ['20 Ω', '40 Ω', '100 Ω'], 'Paralelde R/4 = 5 olduğundan her direnç 20 Ω\'dur. Seri eşdeğeri 4 × 20 = 80 Ω olur.'),
  ('Direnci 16 Ω olan düzgün bir tel, dört eşit parçaya kesilip parçalar birbirine paralel bağlanıyor. Eşdeğer direnç kaç ohm olur?', '1 Ω', ['4 Ω', '0,25 Ω', '16 Ω'], 'Her parçanın direnci 4 Ω\'dur. Dört parça paralel bağlanınca R_eş = 4/4 = 1 Ω olur.'),
  ('Bir üretecin emk\'sı ε, iç direnci r\'dir. Dış direnç, dış devreye en çok gücü aktaracak biçimde R = r seçildiğinde üretecin verimi yüzde kaç olur?', '%50', ['%100', '%25', '%75'], 'Verim η = R/(R+r) olduğundan R = r için η = 1/2 yani %50\'dir. Güç aktarımı en büyüktür ama enerjinin yarısı iç dirençte ısıya dönüşür.'),
  ('10 Ω\'luk bir direnci ölçmek için kurulan düzenekte, direncin uçlarına iç direnci 1 kΩ olan bir voltmetre paralel bağlanmıştır. Voltmetre ve direncin birlikte oluşturduğu eşdeğer direnç yaklaşık kaç ohmdur?', '9,9 Ω', ['10 Ω', '10,1 Ω', '5 Ω'], '10 Ω ile 1000 Ω paralel bağlandığında (10·1000)/1010 ≈ 9,9 Ω olur. Küçük direnç ölçümünde voltmetre etkisi küçüktür.'),
  ('Bir direnç ölçümünde ampermetre, dirençle seri bağlıdır ve voltmetre ikisinin birleşik uçlarına bağlıdır. Ampermetrenin iç direnci 0,5 Ω, gerçek direnç 4,5 Ω ise voltmetre ve ampermetre değerlerinden hesaplanan direnç kaç ohm olur?', '5 Ω', ['4,5 Ω', '4 Ω', '0,5 Ω'], 'Voltmetre hem direncin hem ampermetrenin gerilimini ölçer. Hesaplanan R = 4,5 + 0,5 = 5 Ω\'dur; hata, ampermetre direncinden kaynaklanır.'),
  ('Termostatlı 1000 W\'lık bir ütü, çalıştığı sürenin %60\'ında elektrik çekmektedir. 5 saatlik kullanımda tükettiği enerji kaç kWh\'tir?', '3 kWh', ['5 kWh', '0,6 kWh', '2 kWh'], 'Ortalama güç 1000 × 0,6 = 600 W\'tır. Enerji 0,6 kW × 5 h = 3 kWh olur.'),
  ('Bir direncin uçlarına 2 V, 4 V ve 6 V uygulandığında akımlar 0,40 A, 0,70 A ve 0,90 A ölçülüyor. Bu eleman hakkında ne söylenebilir?', 'Omik değildir, çünkü V/I oranı sabit değildir', ['Omiktir, çünkü akım gerilimle artıyor', 'Omiktir ve direnci 5 Ω\'dur', 'Omik değildir, çünkü akım azalıyor'], 'V/I oranı sırasıyla 5, 5,7 ve 6,7 Ω\'dur. Oran sabit olmadığından eleman Ohm yasasına uymaz.'),
  ('Bir devrede iki özdeş direncin seri bağlı eşdeğerinin, paralel bağlı eşdeğerine oranı kaçtır?', '4', ['2', '1/4', '1/2'], 'R özdeş dirençler için seri eşdeğer 2R, paralel eşdeğer R/2\'dir. Oran 2R / (R/2) = 4\'tür.'),
  ('Üç özdeş R direnci ile elde edilebilecek en küçük ve en büyük eşdeğer dirençlerin (üçü de kullanılmak şartıyla) oranı kaçtır?', '9', ['3', '6', '1/9'], 'En küçük değer paralelde R/3, en büyük değer seride 3R\'dir. Oran 3R / (R/3) = 9\'dur.'),
  ('12 V\'luk bir kaynağın uçlarına seri bağlı R₁ = 2 Ω ve R₂ = 4 Ω dirençleri ile bir lamba bağlanmıştır; lambanın uçlarındaki gerilim 6 V\'tur. Lambanın direnci kaç ohmdur?', '6 Ω', ['2 Ω', '12 Ω', '3 Ω'], 'Dirençlerde toplam 6 V düşer: lambada kalan 6 V\'tur. Seri devrede akım I = 6/(2+4) = 1 A\'dir; lamba direnci 6/1 = 6 Ω\'dur.'),
  ('12 V\'luk bir kaynağa iki kol paralel bağlanmıştır. Birinci kolda 4 Ω ve 8 Ω, ikinci kolda 6 Ω ve 6 Ω seri bağlıdır. Her kolun orta noktası arasına ideal bir voltmetre bağlanırsa (alt dirençler 8 Ω ve 6 Ω) kaç volt gösterir?', '2 V', ['0 V', '6 V', '4,5 V'], 'Birinci koldaki orta nokta, alt uca göre 12 × 8/12 = 8 V\'ta; ikinci koldaki orta nokta 12 × 6/12 = 6 V\'tadır. Fark 2 V\'tur.'),
  ('Emk\'sı 1,5 V ve iç direnci 0,3 Ω olan üç özdeş pil paralel bağlanıp 0,4 Ω\'luk bir dirence bağlanıyor. Her bir pilden geçen akım kaç amperdir?', '1 A', ['3 A', '0,5 A', '1,5 A'], 'Eşdeğer iç direnç 0,1 Ω\'dur. Toplam akım 1,5/(0,4+0,1) = 3 A; üç özdeş pil eşit paylaşır ve her birinden 1 A geçer.'),
  ('Çapı 1 mm olan bakır bir telin uzunluğu 10 m\'dir (ρ = 1,7 × 10⁻⁸ Ω·m). Telin direnci yaklaşık kaç ohmdur?', '0,22 Ω', ['2,2 Ω', '0,017 Ω', '0,43 Ω'], 'Kesit alanı A = π(0,5×10⁻³)² ≈ 7,85×10⁻⁷ m²\'dir. R = ρL/A = 1,7×10⁻⁸ × 10 / 7,85×10⁻⁷ ≈ 0,22 Ω.'),
  ('Aynı uzunlukta ve aynı dirençte bir bakır ve bir alüminyum tel yapılacaktır (ρ_Cu = 1,7 × 10⁻⁸, ρ_Al = 2,8 × 10⁻⁸ Ω·m). Alüminyum telin kesit alanı bakır telin yaklaşık kaç katı olmalıdır?', '1,65 katı', ['0,6 katı', '2,8 katı', '2,72 katı'], 'Aynı R ve L için A, özdirençle orantılıdır: A_Al/A_Cu = 2,8/1,7 ≈ 1,65.'),
  ('Sabit bir şebeke gerilimine bağlı bir akkor lambanın direnci, anahtar kapatıldıktan sonra zamanla nasıl değişir ve bunun sonucu olarak akım nasıl davranır?', 'Direnç artar; akım büyük değerden azalarak kararlı değere iner', ['Direnç azalır; akım zamanla artarak çalışma değerine yükselir', 'Direnç sabit kalır; akım sabit kalır', 'Direnç artar; akım zamanla artar'], 'Flaman ısındıkça direnci büyür. Gerilim sabit olduğundan akım ilk anda büyük, sonra I = V/R ile azalarak çalışma değerine yerleşir.'),
  ('Bir bakır telin direncini %20 artırmak için tel sıcaklığı yaklaşık kaç derece artırılmalıdır? (α = 4 × 10⁻³ /°C)', '50 °C', ['20 °C', '80 °C', '500 °C'], 'ΔR/R = αΔT olduğundan 0,20 = 4×10⁻³ × ΔT ve ΔT = 50 °C\'dir.'),
  ('Aynı akım şiddetinin geçtiği iki tel aynı maddeden yapılmıştır; birinin çapı diğerinin iki katıdır ve uzunlukları eşittir. Kalın telde harcanan güç ince telde harcanan gücün kaç katıdır?', '1/4', ['1/2', '2', '4'], 'Aynı akımda P = I²R\'dir. Kalın telin alanı 4 katı olduğundan direnci dörtte biridir; gücü de 1/4\'tür.'),
  ('Konutlarda kullanılan standart kaçak akım koruma rölelerinin (can güvenliği için) anma kaçak akım değeri genellikle kaç miliamperdir?', '30 mA', ['3 A', '300 A', '0,3 mA'], 'Can güvenliği amaçlı kaçak akım koruma rölelerinde standart değer 30 mA\'dir; bu değere ulaşan fark akımında röle devreyi çok kısa sürede keser.'),
  ('Metal gövdeli bir çamaşır makinesinin gövdesi topraklanmamıştır ve içeride bir faz teli gövdeye temas etmiştir. Makineye dokunan kişi için ne olur?', 'Akım kişiden toprağa akabilir ve elektrik çarpması oluşur', ['Hiçbir şey olmaz, çünkü gövde yalıtkan malzemeden yapılmıştır ve akım geçmez', 'Sigorta hemen devreyi her zaman keser', 'Akım yalnızca makine içinde dolaşır'], 'Gövde fazla temas ettiğinde gerilimli hâle gelir. Toprak bağlantısı yoksa kaçak akım kişinin vücudundan toprağa geçebilir; topraklı sistemde ise akım toprağa akar ve koruma devreyi keser.'),
  ('Kısa devre ile aşırı yüklenme arasındaki temel fark aşağıdakilerden hangisidir?', 'Kısa devrede akım düşük dirençli bir yoldan akar, aşırı yüklenmede çok sayıda cihaz toplam akımı artırır', ['İkisi de yalnızca gerilimin düşmesiyle oluşur', 'Kısa devrede akım sıfırdır, aşırı yüklenmede çok büyüktür', 'Aşırı yüklenme yalnız alternatif akımda olur'], 'Kısa devre, direnci çok küçük bir yolun oluşmasıdır ve akım aniden çok büyür. Aşırı yüklenmede ise çok sayıda cihaz bağlandığı için toplam akım anma değerini aşar.'),
  ('Bir uzatma kablosunun makaraya sarılı hâlde, tam açılmadan yüksek güçlü bir cihazla kullanılması neden tehlikelidir?', 'Sarılı kablo ısıyı iyi atamaz, aşırı ısınıp yalıtkanı eritebilir', ['Sarılı kablo gerilimi artırır', 'Sarılı kablonun direnci sıfır olur', 'Sarılı kablo akımı tamamen keser'], 'Kabloda I²R ısısı açığa çıkar; makara üzerinde sıkı sarılmış kablo bu ısıyı çevreye veremeyip ısınır, yalıtkan erir ve yangın çıkabilir.'),
  ('Aynı kablodan geçebilecek en büyük güvenli akımın, kablonun kesit alanı artırıldığında artmasının nedeni nedir?', 'Direnç azalır ve aynı akımda açığa çıkan ısı azalır', ['Kablonun gerilimi artar', 'Kablonun özdirenci artar ve bu yüzden akım daha kolay geçer', 'Akım yalnız yüzeyden akar'], 'Kesit alanı artınca direnç azalır. Aynı akımda I²R ısı kaybı küçülür; kablo aşırı ısınmadan daha büyük akım taşıyabilir.'),
  ('Bir devrede A anahtarı, birbirine paralel B ve C anahtarlarıyla seri bağlanmıştır; devre lambaya bağlıdır. Lamba hangi durumda yanar?', 'A kapalı ve B ile C\'den en az biri kapalıyken', ['A, B ve C açıkken', 'Yalnız A açıkken', 'Yalnız B ve C kapalı, A açıkken'], 'A seri olduğu için kapalı olmak zorundadır. B ve C paralel olduğundan bunlardan en az birinin kapalı olması yolu tamamlar.'),
  ('Üç fazlı bir şebekede fazlar arasındaki gerilim, faz–nötr geriliminin yaklaşık kaç katıdır?', '√3 katı', ['1,5 katı', 'Yarısı', '√2 katı'], 'Faz–faz gerilimi faz–nötr geriliminin √3 katıdır. 220 V için bu yaklaşık 380 V eder.'),
  ('Bir lambanın üzerinde \'IP65\' gibi bir yazı olması neyi gösterir?', 'Toz ve su püskürtmesine karşı koruma derecesini', ['Lambanın gücünü', 'Lambanın renk sıcaklığını ve ışık veriminin lümen değerini', 'Lambanın şebeke frekansını'], 'IP (Ingress Protection) kodu, cihazın katı cisimlere (toz) ve sıvılara karşı koruma düzeyini belirtir; rakamlar bu düzeyleri verir.'),
  ('Kuru bir insan derisinin direnci yaklaşık 100 kΩ, ıslak derinin direnci yaklaşık 1 kΩ kabul edilirse 220 V\'ta ıslak deriden geçen akım kuru deriden geçenin kaç katıdır?', '100 katı', ['10 katı', '2,2 katı', '1000 katı'], 'Aynı gerilimde akım dirençle ters orantılıdır. Direnç 100 kat azaldığı için akım 100 kat artar.'),
  ('Evde elektrik tamiri yapmadan önce yalnızca anahtarı kapatmak yerine ana sigortayı kapatmak neden daha güvenlidir?', 'Anahtar fazı kesmemiş olabilir; ana sigorta tüm devreyi gerilimsiz bırakır', ['Anahtar akımı artırır', 'Sigorta gerilimi yükseltir', 'Anahtar toprak bağlantısını keser'], 'Anahtar yanlışlıkla nötr hattına bağlıysa lamba yuvası gerilimli kalabilir. Ana sigorta bütün hattı keserek çarpılma riskini ortadan kaldırır.'),
  ('1/4 W güç değerli 100 Ω\'luk bir karbon direncin uçlarına aşırı ısınmadan uygulanabilecek en büyük gerilim kaç volttur?', '5 V', ['25 V', '2,5 V', '0,5 V'], 'P = V²/R olduğundan V = √(P·R) = √(0,25 × 100) = 5 V\'tur.'),
  ('1/4 W güç değerli bir direncin, 12 V\'luk bir kaynağa doğrudan bağlanabilmesi için direnci en az kaç ohm olmalıdır?', '576 Ω', ['48 Ω', '3 Ω', '1,44 Ω'], 'Gerekli koşul P = V²/R ≤ 0,25 W\'tır. R ≥ 144/0,25 = 576 Ω olmalıdır.'),
  ('Her biri 100 Ω ve 1/4 W olan iki direnç seri bağlanıyor. Bu bileşime ısınma sınırı aşılmadan uygulanabilecek en büyük gerilim kaç volttur?', '10 V', ['5 V', '20 V', '7,07 V'], 'Her direnç en fazla 50 mA taşıyabilir. Seri bağlamada akım ortak olduğundan en fazla 50 mA geçer ve gerilim 0,05 × 200 = 10 V olur.'),
  ('Bir NTC termistör, gerilim bölücünün alt kolunda sabit bir dirençle seri bağlanmıştır. Sıcaklık artarsa termistörün uçlarındaki çıkış gerilimi nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar sonra sıfır olur'], 'NTC\'nin direnci sıcaklıkla azalır; bölücüde alt direncin payı küçüldüğü için çıkış gerilimi de düşer.'),
  ('12 V\'luk kaynağa 3 adet LED seri bağlanıyor; her LED 3 V\'ta 20 mA ile çalışmaktadır. Seri koruma direnci kaç ohm olmalıdır?', '150 Ω', ['450 Ω', '600 Ω', '50 Ω'], 'LED\'ler toplam 9 V düşürür. Dirençte 3 V kalır: R = 3/0,02 = 150 Ω\'dur.'),
  ('12 V\'luk kaynağa, her biri 3 adet LED ve 150 Ω\'luk dirençten oluşan iki özdeş kol paralel bağlanmıştır. Her LED 20 mA ile çalışmaktadır. Kaynaktan çekilen güç kaç watttır?', '0,48 W', ['0,24 W', '0,96 W', '1,2 W'], 'Kollardan 20\'şer mA geçer; toplam akım 40 mA\'dir. P = V·I = 12 × 0,04 = 0,48 W olur.'),
  ('Bir evin elektrik sayacı 30 günlük dönem başında 12 345 kWh, sonunda 12 705 kWh göstermektedir. Evin bu dönemdeki ortalama gücü kaç watttır?', '500 W', ['12 W', '360 W', '5000 W'], 'Tüketim 360 kWh\'tir. Dönem 720 saat olduğundan ortalama güç 360/720 = 0,5 kW = 500 W\'tır.'),
  ('Bir klima 3500 W soğutma gücü sağlamakta ve performans katsayısı (COP) 3,5 olmaktadır. Klimanın şebekeden çektiği elektrik gücü kaç watttır?', '1000 W', ['12 250 W', '3500 W', '10 W'], 'COP = soğutma gücü / elektrik gücü olduğundan elektrik gücü 3500/3,5 = 1000 W\'tır.'),
  ('Yararlı mikrodalga çıkış gücü 800 W olan bir fırının verimi %60\'tır. Şebekeden çektiği güç yaklaşık kaç watttır?', '1333 W', ['480 W', '800 W', '1600 W'], 'Giriş gücü, çıkış gücünün verime bölünmesiyle bulunur: 800/0,60 ≈ 1333 W.'),
  ('12 V ve 50 Ah\'lik bir akü %40 doludur. 10 A\'lik sabit akımla tamamen doldurulursa (kayıplar ihmal) kaç saat sürer?', '3 saat', ['2 saat', '5 saat', '30 saat'], 'Eksik yük 50 × 0,6 = 30 Ah\'tir. Süre = 30/10 = 3 saattir.'),
  ('Etiketinde \'1000 W, 220 V\' yazılı bir ısıtıcı yanlışlıkla 110 V\'luk bir şebekeye bağlanırsa (direnç sabit) çektiği akım ilk anma akımının kaç katı olur?', '1/2', ['2', '1/4', '4'], 'Direnç sabit kalırsa akım gerilimle orantılıdır; gerilim yarıya inince akım da yarıya iner. Güç ise dörtte birine düşer.'),
  ('Bir motorun elektrik girişi 200 W, yararlı çıkışı 150 W\'tır. Motorda bir saatte ısıya dönüşen enerji kaç kJ\'dür?', '180 kJ', ['540 kJ', '720 kJ', '50 kJ'], 'Kayıp güç 50 W\'tır. Bir saatte kayıp enerji 50 × 3600 = 180 000 J = 180 kJ\'dür.'),
  ('Özdeş L₁, L₂, L₃ ve L₄ lambalarından L₁ ile L₂ seri bir kol, L₃ ile L₄ seri başka bir kol oluşturmuş ve iki kol birbirine paralel bağlanıp ideal bir üretece takılmıştır. L₁ lambası yuvasından çıkarılırsa diğer lambalara ne olur?', 'L₂ söner; L₃ ve L₄ aynı parlaklıkta yanmaya devam eder', ['Dördü de söner', 'L₃ ve L₄ daha parlak yanar', 'L₂ daha parlak yanar'], 'L₁ çıkarılınca birinci kol açılır ve L₂ akımsız kalır. İdeal üretecin ikinci kolun gerilimi değişmediğinden L₃ ve L₄ aynı parlaklıkta yanar.'),
  ('Bir üretece R₁ direnci, birbirine paralel R₂ ve R₃ dirençleriyle seri bağlanmıştır. R₃\'ün değeri artırılırsa R₁\'in uçlarındaki gerilim nasıl değişir? (İdeal üreteç)', 'Azalır', ['Artar', 'Değişmez', 'Önce artar, sonra azalır'], 'R₃ artınca paralel grubun direnci büyür, toplam direnç artar ve akım azalır. R₁\'in uçlarındaki gerilim I·R₁ olduğundan azalır.'),
  ('Her kenarı R direncinde olan düzgün altıgen tel çerçevenin karşıt iki köşesi arasındaki eşdeğer direnç kaç R\'dir?', '3R/2', ['R', '3R', '6R/5'], 'Karşıt köşeler arasında her biri 3 kenarlık (3R) iki yol vardır. Paralel eşdeğeri 3R/2 olur.'),
  ('Altı özdeş R direnci halka biçiminde uç uca eklenmiştir. Halkanın birbirine bitişik iki bağlantı noktası devreye alınırsa eşdeğer direnç nedir?', '5R/6', ['R/2', '3R/2', 'R/6'], 'Komşu köşeler arasında R\'lik bir yol ve 5R\'lik diğer yol vardır. Paralel eşdeğeri (R·5R)/(6R) = 5R/6\'dır.'),
  ('2R, 3R ve 6R dirençleri birbirine paralel bağlanırsa eşdeğer direnç kaç R olur?', 'R', ['2R', 'R/2', '11R'], '1/R_eş = 1/(2R) + 1/(3R) + 1/(6R) = (3 + 2 + 1)/(6R) = 1/R olduğundan R_eş = R\'dir.'),
  ('Dört özdeş lamba, ikişerli seri iki kol oluşturacak ve bu kollar paralel bağlanacaktır. Her lamba 220 V\'luk gerilimde 100 W harcıyorsa devre 440 V\'luk bir kaynağa bağlandığında toplam güç kaç watt olur?', '400 W', ['200 W', '800 W', '100 W'], 'Her kolda iki lamba 440 V\'u paylaşır; her lamba 220 V alır ve 100 W harcar. Dört lamba toplam 400 W harcar.'),
  ('Özdeş iki lamba önce seri, sonra paralel olarak aynı kaynağa bağlanıyor. Paralel bağlamada harcanan toplam güç, seri bağlamadakinin kaç katıdır?', '4 katı', ['2 katı', '1/2 katı', '8 katı'], 'Seri eşdeğer 2R, paralel eşdeğer R/2\'dir. Aynı gerilimde P = V²/R olduğundan güç oranı 2R/(R/2) = 4\'tür.'),
  ('Bir devrede iki özdeş lamba seri bağlanmış, ardından aynı kaynağa paralel olarak üçüncü bir özdeş lamba eklenmiştir. Seri lambaların her birinin gücü, üçüncü lambanın gücünün kaç katıdır?', '1/4', ['1/2', '2', '4'], 'Seri lambaların her biri V/2 gerilimi alır; üçüncü lamba V alır. P ∝ V² olduğundan oran (1/2)² = 1/4\'tür.'),
  ('5 Ω\'luk bir direnç, birbirine paralel 10 Ω ve 10 Ω\'luk dirençlerle seri bağlanıp 30 V\'a bağlanıyor. 5 Ω\'luk dirençte harcanan güç kaç watttır?', '45 W', ['80 W', '20 W', '180 W'], 'Paralel grup 5 Ω\'dur; toplam 10 Ω ve akım 3 A\'dir. 5 Ω\'da P = I²R = 9 × 5 = 45 W olur.'),
  ('Bir lambayı iki farklı yerden (örneğin merdivenin altından ve üstünden) bağımsız olarak açıp kapatmak için hangi tür anahtarlar kullanılır?', 'İki adet çift yönlü (merdiven/komütatör) anahtar', ['İki adet tek yönlü anahtar birbirine paralel bağlanmalıdır', 'Bir adet basma düğmesi ile bir sigorta seri kullanılmalıdır', 'İki adet diyot ters yönlerde birbirine paralel bağlanmalıdır'], 'Çift yönlü anahtarlar, iki ayrı yol arasında seçim yapar; ikisi birlikte bağlandığında herhangi birinin konumunu değiştirmek lambanın durumunu tersine çevirir.'),
  ('Bir buzdolabında iç aydınlatma lambası ile kompresör motoru birbirine hangi biçimde bağlıdır ve neden?', 'Paralel; lamba kapı açılınca yanarken motor kendi termostatıyla bağımsız çalışsın diye', ['Seri; ikisi aynı akımı paylaşsın ve toplam gerilimi bölsün diye', 'Seri; lamba yanınca motorun hızı otomatik düşsün diye', 'Hiç bağlı değildir; lamba ve motor birbirinden tamamen ayrı iki şebekeden beslenir'], 'Lamba ve motor aynı şebeke geriliminde, birbirinden bağımsız çalışmalıdır. Paralel bağlamada her biri kendi anahtarı veya termostatıyla kontrol edilir.'),
  ('Bazı seri bağlı yılbaşı ışık dizilerinde bir ampul yansa bile dizinin geri kalanı yanmaya devam eder. Bu durumu sağlayan düzenek nedir?', 'Her ampulün yanında, ampul yanınca akımı geçiren bir şönt (köprüleme) teli bulunur', ['Ampuller aslında paralel bağlıdır ve dizi bunu gizler', 'Dizideki her ampulün içinde ayrı bir küçük pil bulunur', 'Ampullerin telleri özel alaşım kullanıldığından hiçbir koşulda kopmaz'], 'Ampul teli koptuğunda uçlar arasında yüksek gerilim oluşur ve ampule paralel şönt teli iletime geçerek akımı ampulü atlayarak geçirir; dizinin kalanı yanmaya devam eder.'),
  ('Elektronik cihazların giriş kısmına ters yönde bir diyot (veya cihaza seri bir diyot) konmasının amacı nedir?', 'Pilin ters bağlanması durumunda cihazı korumak', ['Akımı iki katına çıkararak cihazı hızlandırmak', 'Gerilimi sabit tutarak çıkışı dengelemek', 'Cihazı daha sıcak çalıştırarak verimini artırmak'], 'Diyot yalnızca ileri yönde iletir; kaynak ters bağlanırsa akım geçmez ve devre elemanları zarar görmez.'),
  ('12 V ve 1 A çıkış değerli bir adaptörle, 12 V ve 2 A çeken bir cihaz çalıştırılmaya çalışılırsa ne olması beklenir?', 'Adaptör aşırı yüklenir, ısınır ve gerilimi düşer ya da koruması devreye girer', ['Cihaz iki kat güçle çalışır ve adaptör bundan etkilenmez', 'Adaptör akımı otomatik olarak iki katına çıkarıp gerilimi artırır', 'Hiçbir etkisi olmaz, çünkü adaptör akımı cihaza göre sınırsız ayarlar'], 'Cihazın talebi adaptörün anma akımını aşıyor. Adaptör ısınır, uç gerilimi düşer ya da koruma devresi kapanır; uzun süreli kullanımda arıza ve yangın riski vardır.'),
  ('Ütülerde, tost makinelerinde ve elektrikli ısıtıcılarda sıcaklığı sınırlamak için kullanılan bimetal şeritli termostat nasıl çalışır?', 'Isınınca farklı genleşen iki metal bükülüp kontağı açar, soğuyunca tekrar kapatır', ['Isınınca direnci sıfır olur ve devre doğrudan kapanır', 'Isınınca kendi içinde gerilim üretip devreyi besler', 'Isınınca kondansatör gibi yük depolar ve akımı sönümler'], 'Bimetalde iki metal farklı oranda genleşir; ısınan şerit bükülerek devreyi keser, soğuyunca eski hâline gelip devreyi yeniden kapatır.'),
  ('Gerilimi sabit olan bir kaynağa bağlı elektrikli ısıtıcıyı daha düşük güçte çalıştırmak için en uygun yöntem aşağıdakilerden hangisidir?', 'Rezistans devresine seri bir direnç eklemek ya da rezistansların bağlantısını seriye çevirmek', ['Rezistansa paralel bir direnç eklemek ve toplam direnci azaltmak', 'Rezistansı iletken telle kısa devre ederek akımı sınırlamak', 'Gerilimi yükseltip direnci aynı bırakmak'], 'Toplam direnç artınca akım ve P = V²/R gücü azalır. Paralel direnç, kısa devre ve gerilim artışı gücü artırır.'),
  ('Akım değeri küçük, gerilimi yüksek bir iletim hattı ile akım değeri büyük, gerilimi düşük bir hat aynı gücü taşıyor. Hangi hatta Joule ısınma kaybı daha büyüktür ve neden?', 'Akımı büyük olan hatta, çünkü kayıp I²R ile orantılıdır', ['Gerilimi yüksek olan hatta, çünkü kayıp gerilimle orantılıdır', 'İkisinde de eşittir, çünkü iletilen güç aynıdır', 'Akımı küçük olan hatta, çünkü yüksek gerilimde ısı artar'], 'Aynı güçte P = VI olduğundan yüksek gerilimde akım küçük, düşük gerilimde büyüktür. Isı kaybı I²R olduğundan akımın büyük olduğu hatta kayıp daha fazladır.'),
  ('Çok kullanılan bir uzatma kablosunun fişi veya priz kontağı, uzun süre yüksek güçle çalışmanın ardından sıcak ve yumuşamış bulunuyor. Bunun fiziksel nedeni nedir?', 'Kontak yüzeylerindeki yüksek temas direncinde I²R ısısı açığa çıkması', ['Kontakta gerilimin sıfır olması ve akımın yalnızca yüzeyden akması', 'Kabloda akımın hiç geçmemesi nedeniyle statik yüklerin birikmesi', 'Kontağın alternatif akımı doğru akıma çevirip ısıyı artırması'], 'Gevşek veya oksitlenmiş kontaklarda temas direnci yükselir; büyük akımda I²R ısınması artar ve plastik yumuşar.'),
  ('Bir telde elektronların sürüklenme hızı 0,5 mm/s ise bir elektronun telin 1 metrelik bölümünü geçmesi yaklaşık ne kadar sürer?', '2000 s (yaklaşık 33 dakika)', ['2 saat (yaklaşık 7200 saniye)', '0,5 s', '20 s'], 'Süre t = yol/hız = 1 m / (0,5×10⁻³ m/s) = 2000 s\'dir. Lambanın hemen yanması, elektronların değil elektrik alanın hızlı yayılmasından kaynaklanır.'),
  ('Bir devrede akım ilk 2 saniyede sıfırdan 4 A\'e doğrusal artıyor, sonraki 4 saniye boyunca 4 A\'de sabit kalıyor. Toplam 6 saniyede devreden geçen yük kaç coulomb olur?', '20 C', ['24 C', '16 C', '12,5 C'], 'İlk 2 saniyedeki yük, ortalama akımla bulunur: ½ × 4 × 2 = 4 C. Sonraki 4 saniyede 4 × 4 = 16 C geçer. Toplam 20 C\'dir.'),
  ('Bir parçacık demetinde her saniye 10¹⁸ tane alfa parçacığı (yükü +2e) bir kesitten geçmektedir. Demetin akımı kaç amperdir? (e = 1,6 × 10⁻¹⁹ C)', '0,32 A', ['0,16 A', '1,6 A', '3,2 A'], 'Saniyede geçen yük 10¹⁸ × 2 × 1,6×10⁻¹⁹ = 0,32 C\'dur; bu yüzden akım 0,32 A\'dir.'),
  ('Bir elektrik motoru 24 V\'ta 5 A akım çekmekte ve 90 W mekanik güç vermektedir. Motorun verimi yüzde kaçtır?', '%75', ['%25', '%90', '%120'], 'Giriş gücü 24 × 5 = 120 W\'tır. Verim 90/120 = 0,75 yani %75\'tir; 30 W ısıya dönüşür.'),
  ('Direnci 22 Ω olan bir ısıtıcı rezistansı 220 V\'a bağlanıp 10 dakika çalıştırılıyor. Açığa çıkan ısı enerjisi kaç joule\'dür?', '1,32 × 10⁶ J', ['2,2 × 10³ J', '1,32 × 10⁴ J', '2,64 × 10⁵ J'], 'Güç P = V²/R = 220²/22 = 2200 W\'tır. Enerji = 2200 × 600 = 1,32×10⁶ J olur.'),
  ('3 Ω ve 6 Ω\'luk dirençler paralel bağlanmış, bu grup 4 Ω\'luk bir dirençle seri bağlanıp 24 V\'a bağlanmıştır. Devrenin harcadığı toplam güç kaç watttır?', '96 W', ['144 W', '48 W', '288 W'], 'Eşdeğer direnç 2 + 4 = 6 Ω\'dur. P = V²/R = 576/6 = 96 W\'tır.'),
  ('Emk\'sı 1,5 V ve iç direnci 0,2 Ω olan iki özdeş pil seri bağlanıp uçları iletken telle birleştirilirse kısa devre akımı kaç amper olur?', '7,5 A', ['3,75 A', '15 A', '1,5 A'], 'Toplam emk 3 V, toplam iç direnç 0,4 Ω\'dur. Kısa devre akımı I = 3/0,4 = 7,5 A\'dir.'),
  ('Direnci 12 Ω olan bir tel üç eşit parçaya kesilip parçalar seri, sonra aynı parçalar paralel bağlanıyor. Seri eşdeğerin paralel eşdeğere oranı kaçtır?', '9', ['3', '1/9', '6'], 'Seri eşdeğer 12 Ω\'dur. Her parça 4 Ω olduğundan paralel eşdeğer 4/3 Ω\'dur. Oran 12/(4/3) = 9\'dur.'),
  ('Gerilim 12 V olan bir kaynağa bağlı bir telin direnci 6 Ω\'dur. Telin uzunluğu iki katına çıkarılır ve kesiti aynı kalırsa tel üzerinde harcanan güç kaç watt olur?', '12 W', ['24 W', '6 W', '48 W'], 'İlk güç 144/6 = 24 W\'tır. Direnç 12 Ω olunca güç 144/12 = 12 W\'a düşer.'),
  ('Gerilim (V) düşey, akım (I) yatay eksende çizilen ve orijinden geçen doğrulardan birinin eğimi diğerinin iki katıdır. Hangisinin direnci daha büyüktür ve kaç katıdır?', 'Eğimi büyük olanın, 2 katı', ['Eğimi küçük olanın, 2 katı', 'İkisinin direnci eşittir', 'Eğimi büyük olanın, 4 katı'], 'V–I grafiğinin eğimi V/I = R\'dir. Eğimi iki kat büyük olan iletkenin direnci de iki kat büyüktür.'),
  ('Seri bağlı dirençlerden oluşan bir devre için aşağıdaki ifadelerden hangisi yanlıştır? (Kaynak ideal ve gerilimi sabittir)', 'Dirençlerden birinin değeri artarsa diğer dirençlerin uçlarındaki gerilimler de artar', ['Devrenin her noktasından geçen akım şiddeti aynıdır', 'Eşdeğer direnç, dirençlerin toplamına eşittir', 'Kaynak gerilimi, dirençlerin değerleriyle doğru orantılı olarak dirençler arasında paylaşılır'], 'Bir direnç artınca toplam direnç artar ve akım azalır; böylece değeri değişmeyen dirençlerin gerilimleri azalır. Gerilimin kaynak geriliminin büyük kısmı artan direncin üzerinde toplanır.'),
  ('Kondansatörlerle ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Paralel bağlı kondansatörlerin eşdeğer sığası, en küçük sığadan da küçüktür', ['Seri bağlı kondansatörlerin her birinde biriken yük aynıdır, çünkü ortadaki levhalar yalıtılmış sistemdir', 'Paralel bağlı kondansatörlerin uçlarındaki gerilim aynıdır', 'Levhalar arası uzaklık azaldıkça sığa artar'], 'Paralel bağlamada sığalar toplanır; eşdeğer sığa her bir sığadan büyüktür. Seri bağlamada ise eşdeğer sığa en küçük sığadan küçüktür.'),
  ('İç direnci olan bir üreteç için aşağıdakilerden hangisi yanlıştır?', 'Üreteçten akım çekildikçe uç gerilimi emk\'dan büyük olur', ['Devreden akım çekilmiyorsa uç gerilimi emk\'ya eşittir, çünkü iç dirençte gerilim düşmez', 'Çekilen akım arttıkça uç gerilimi azalır', 'Kısa devre akımı ε/r değerine eşittir'], 'Uç gerilimi V = ε − I·r olduğundan akım çekilirken emk\'dan her zaman küçüktür; yalnızca üreteç şarj edilirken uç gerilimi emk\'dan büyük olabilir.'),
  ('Joule ısınması ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Aynı kaynağa paralel bağlı dirençler arasında en büyük direnç en çok ısınır', ['Seri bağlı dirençler arasında en büyük direnç en çok ısınır, çünkü akım ortaktır', 'Isı enerjisi Q = I²Rt bağıntısıyla hesaplanır', 'Aynı gerilimde direnç küçüldükçe birim zamanda açığa çıkan ısı artar'], 'Paralelde gerilim ortaktır ve P = V²/R olduğundan en küçük direnç en çok ısınır; seride ise akım ortaktır ve büyük direnç daha çok ısınır.'),
  ('Wheatstone köprüsüyle ilgili aşağıdakilerden hangisi yanlıştır?', 'Denge durumunda köprü uçları arasındaki potansiyel farkı kaynak gerilimine eşittir', ['Denge durumunda köprü kolundan akım geçmez, çünkü kol uçları aynı potansiyeldedir', 'Denge koşulu P/Q = R/S biçimindedir', 'Bilinmeyen direnci hassas ölçmekte kullanılır'], 'Denge durumunda köprünün iki ucu aynı potansiyeldedir ve aralarındaki potansiyel farkı sıfırdır; bu yüzden köprü kolundan akım geçmez.'),
  ('Elektriksel güçle ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Gerilim sabitken direnç artarsa direncin harcadığı güç artar', ['Akım sabitken direnç artarsa harcanan güç de artar, çünkü P = I²R bağıntısı geçerlidir', 'Aynı akımda gerilimi büyük olan eleman daha büyük güç harcar', 'Güç; akım ile gerilimin çarpımına eşittir'], 'P = V²/R olduğundan gerilim sabitken direnç arttıkça güç azalır. Akım sabitken ise P = I²R olduğundan direnç ile birlikte artar.'),
  ('Küçükten büyüğe doğru eşdeğer dirençlere göre sıralama: A düzeninde 6 Ω ve 3 Ω paralel, B düzeninde iki 2 Ω seri, C düzeninde 12 Ω ve 4 Ω paralel bağlanmıştır. Sıralama hangisidir?', 'A < C < B', ['A < B < C', 'B < C < A, yani B en küçüktür', 'C < A < B'], 'A: 2 Ω, B: 4 Ω, C: (12·4)/16 = 3 Ω\'dur. Küçükten büyüğe sıralama A < C < B\'dir.'),
  ('Üç cihazdan A 1500 W ile 20 dakika, B 100 W ile 6 saat, C 800 W ile 40 dakika çalışıyor. Enerji tüketimleri büyükten küçüğe nasıl sıralanır?', 'B > C > A', ['A > C > B, yani en güçlü cihaz en çok harcar', 'C > B > A', 'B > A > C'], 'A: 0,5 kWh, B: 0,6 kWh, C: yaklaşık 0,533 kWh\'tir. Sıralama B > C > A olur.'),
  ('RC devresinde kondansatörün dolması ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Dolma sırasında devre akımı zamanla artarak en büyük değerine ulaşır', ['Dolma süresinin ölçüsü olan zaman sabiti τ = RC\'dir', 'Boş kondansatör başlangıçta kısa devre gibi davranır ve akım en büyük değerindedir', 'Yeterince uzun süre sonra kondansatörden akım geçmez'], 'Dolma sırasında akım başlangıçta en büyüktür (ε/R) ve zamanla azalarak sıfıra iner; yük ise artarak son değerine yaklaşır.'),
  ('Bir devrede ideal bir kaynağa iki direnç paralel bağlıdır; ana koldaki ampermetre toplam akımı gösterir. Kollardan birinin anahtarı açılırsa ampermetre ve kaynağa paralel voltmetre nasıl değişir?', 'Ampermetre azalır, voltmetre değişmez', ['Ampermetre artar, voltmetre azalır', 'İkisi de azalır', 'İkisi de değişmez'], 'Bir kol açılınca toplam direnç artar ve ana akım azalır. İdeal kaynağın gerilimi değişmediğinden voltmetre aynı değeri gösterir.'),
  ('Potansiyometre yöntemiyle emk ölçülürken 1,0 V\'luk standart pil telin 50 cm\'sinde, bilinmeyen pil 75 cm\'sinde denge sağlıyor. Bilinmeyen pilin emk\'sı kaç volttur?', '1,5 V', ['0,67 V', '1,25 V', '2,0 V'], 'Denge uzunlukları emklerle orantılıdır: ε_x = 1,0 × 75/50 = 1,5 V.'),
  ('Bir metalin özdirenci 2,5 × 10⁻⁸ Ω·m ise elektriksel iletkenliği kaç S/m\'dir?', '4 × 10⁷ S/m', ['2,5 × 10⁸ S/m', '4 × 10⁻⁷ S/m', '2,5 × 10⁻⁸ S/m'], 'İletkenlik özdirencin çarpma tersidir: σ = 1/ρ = 1/(2,5×10⁻⁸) = 4×10⁷ S/m\'dir.'),
  ('4 μF\'lık iki kondansatör önce seri, sonra paralel bağlanıp 100 V\'a bağlanıyor. Paralel bağlamada depolanan toplam enerji, seri bağlamada depolananın kaç katıdır?', '4 katı', ['2 katı', '1/4 katı', '16 katı'], 'Seri eşdeğer sığa 2 μF, paralel 8 μF\'tır. U = ½CV² olduğundan aynı gerilimde enerji oranı sığa oranı olan 4\'tür.'),
  ('Üzerinde 100 μF ve 400 V yazan bir elektrolitik kondansatörün en büyük gerilimde depolayabileceği yük kaç milicoulombdur?', '40 mC', ['0,25 mC', '4 mC', '400 mC'], 'q = C·V = 100×10⁻⁶ × 400 = 0,04 C = 40 mC\'dir.'),
  ('12 V\'luk ideal kaynağa 2 kΩ ve 4 kΩ\'luk iki direnç seri bağlıdır ve 5 μF\'lık bir kondansatör 4 kΩ\'luk dirence paralel bağlanmıştır. Kararlı duruma ulaşıldığında kaynaktan çekilen akım kaç miliamperdir?', '2 mA', ['3 mA', '6 mA', '0 mA'], 'Kondansatörden akım geçmediğinden toplam direnç 6 kΩ\'dur. I = 12/6000 = 2×10⁻³ A = 2 mA\'dir.'),
  ('Tek bir rezistansla 10 dakikada kaynayan bir miktar su, bu rezistansa özdeş ikinci bir rezistans seri bağlanıp aynı şebekeden ısıtılırsa kaç dakikada kaynar? (Isı kaybı yok)', '20 dakikada', ['5 dakikada', '10 dakikada', '40 dakikada'], 'Seri bağlamada direnç iki katına çıkar, güç yarıya düşer. Aynı ısı için süre iki katına çıkar: 20 dakika.'),
  ('3000 mAh\'lik bir batarya %20 doluluktan tamamen dolana kadar 1,5 A\'lik sabit akımla (kayıpsız) şarj ediliyor. Şarj süresi kaç saat olur?', '1,6 saat', ['2 saat', '0,4 saat', '5 saat'], 'Eksik yük 3000 × 0,8 = 2400 mAh = 2,4 Ah\'tir. Süre = 2,4/1,5 = 1,6 saattir.'),
  ('Dirençlerle ve ampermetreyle yapılan bir ölçümde iç direnci 2 Ω olan ampermetre, 8 Ω\'luk bir dirençle seri bağlanıp 20 V\'luk ideal kaynağa takılıyor. Ampermetre kullanılmasaydı akım 2,5 A olacaktı. Ampermetrenin ölçümde yaptığı bağıl hata yüzde kaçtır?', '%20', ['%25', '%2,5', '%80'], 'Ampermetreli devrede I = 20/10 = 2 A okunur. Gerçek değere göre hata (2,5 − 2)/2,5 = 0,2 yani %20\'dir.'),
  ('Tam ölçek akımı 0,1 A ve iç direnci 9 Ω olan bir ampermetrenin ölçme sınırı 1 A\'e çıkarılacaktır. Paralel bağlanacak şönt direnç kaç ohm olmalıdır?', '1 Ω', ['0,1 Ω', '9 Ω', '10 Ω'], 'Alet gerilimi 0,1 × 9 = 0,9 V\'tur. Şönttten 0,9 A geçeceğinden R = 0,9/0,9 = 1 Ω olmalıdır.'),
  ('Emk\'sı 6 V ve iç direnci 2 Ω olan bir üretece sırasıyla 1 Ω, 2 Ω, 4 Ω ve 9 Ω\'luk dış dirençler ayrı ayrı bağlanıyor. Hangisinde dış dirençte harcanan güç en büyüktür?', '2 Ω\'luk dirençte', ['1 Ω\'luk dirençte', '4 Ω\'luk dirençte', '9 Ω\'luk dirençte'], 'Güçler sırasıyla 4, 4,5, 4 ve 2,68 W\'tır. En büyük güç dış direnç iç dirence eşit olduğunda, yani 2 Ω\'ta elde edilir.'),
  ('9 V\'a yüklenmiş bir kondansatör, zaman sabiti 3 s olan bir RC devresiyle boşalıyor. 3 saniye sonra kondansatörün gerilimi yaklaşık kaç volt olur? (e⁻¹ ≈ 0,37)', '3,3 V', ['4,5 V', '6 V', '0 V'], 'Boşalmada V = V₀e^(−t/τ) olduğundan t = τ için V ≈ 9 × 0,37 ≈ 3,3 V olur.'),
  ('18 V ve 4 Ah değerlerinde bir bataryalı matkabın bataryasında depolanan enerji yaklaşık kaç kilojoule\'dür?', '259 kJ', ['72 kJ', '1,2 kJ', '14,4 kJ'], 'Enerji = 18 V × 4 Ah = 72 Wh\'tır. 72 × 3600 = 259 200 J ≈ 259 kJ\'dir.'),
  ('Bir devrede toprak (referans) noktası değiştirildiğinde devre elemanlarının uçlarındaki potansiyeller ve potansiyel farkları nasıl etkilenir?', 'Potansiyel değerleri değişir, potansiyel farkları değişmez', ['Potansiyel değerleri değişmez, ancak potansiyel farkları sıfır noktasına göre değişir', 'Hem değerler hem farklar değişir', 'Hiçbir büyüklük değişmez, çünkü toprak etkisizdir'], 'Potansiyel göreli bir niceliktir; sıfır noktası seçimi tüm potansiyelleri aynı miktarda öteler. Elemanların uçları arasındaki farklar, akımlar ve güçler değişmez.'),
  ('Bir devre elemanı üzerinden geçen akımın yönü, elemanın uçlarındaki potansiyellerden hangisinin daha yüksek olduğunu gösterir?', 'Akım pasif bir dirençte yüksek potansiyelden düşük potansiyele doğru akar', ['Akım pasif bir dirençte düşük potansiyelden yüksek potansiyele doğru ve pil gibi akar', 'Akım yönü potansiyelle ilgisizdir', 'Akım hep eksi uçtan artı uca akar'], 'Geleneksel akım yönü, pasif bir dirençte potansiyelin azaldığı yöndür; direnç üzerinde enerji ısıya dönüştüğü için potansiyel düşer.'),
  ('Sığası C olan bir kondansatör, direnci R olan bir dirençle seri bağlı bir üreteçle dolduruluyor. Direnç iki katına, sığa yarıya indirilirse dolma süresinin ölçüsü olan zaman sabiti nasıl değişir?', 'Değişmez', ['İki katına çıkar', 'Yarıya iner', 'Dört katına çıkar'], 'Zaman sabiti τ = RC\'dir. R iki katına çıkar, C yarıya iner; çarpım aynı kalır ve τ değişmez.'),
  ('Bir akkor lamba yanıp sönen sinyal devresinde kullanılan RC zamanlayıcıda süre uzatılmak isteniyor. Hangisi yapılmalıdır?', 'Direnç ve sığa değerleri birlikte artırılmalıdır', ['Direnç azaltılıp sığa sabit tutulmalı ve gerilim iki katına çıkarılmalıdır', 'Kaynak gerilimi sıfırlanmalıdır', 'Direnç kısa devre edilmelidir'], 'Zaman sabiti τ = RC olduğundan RC çarpımı büyütülürse süre uzar. Direnci azaltmak ya da kısa devre etmek süreyi kısaltır.'),
  ('Gücü 2000 W ve verimi %90 olan bir elektrikli su ısıtıcı, 1,5 kg suyu 20 °C\'den 100 °C\'ye kaç saniyede ısıtır? (c = 4200 J/kg·°C)', '280 s', ['252 s', '168 s', '311 s'], 'Suya gereken ısı 1,5 × 4200 × 80 = 504 000 J\'dür. Elektrik enerjisi 504 000/0,9 = 560 000 J; süre 560 000/2000 = 280 s\'dir.'),
  ('3 kW\'lık elektrikli bir boyler, 80 kg suyu 15 °C\'den 65 °C\'ye (verim %100) yaklaşık kaç saatte ısıtır? (c = 4200 J/kg·°C)', '1,56 saat', ['0,26 saat', '15,6 saat', '4,67 saat'], 'Gereken ısı 80 × 4200 × 50 = 16,8 MJ\'dir. Süre = 16,8×10⁶ / 3000 = 5600 s ≈ 1,56 saattir.'),
  ('Gücü 1200 W olan bir ütünün enerjisinin %50\'si 1 kg\'lık demir tabana (c = 450 J/kg·°C) aktarılıyor. 60 saniyede tabanın sıcaklığı yaklaşık kaç °C artar?', '80 °C', ['160 °C', '40 °C', '8 °C'], 'Tabana aktarılan ısı 600 W × 60 s = 36 000 J\'dür. ΔT = 36 000/(1 × 450) = 80 °C\'dir.'),
  ('Grafit, elmasla aynı karbondan oluşmasına rağmen elektriği ilettiği hâlde elmas yalıtkandır. Bunun temel nedeni nedir?', 'Grafit katmanlarında serbestçe hareket edebilen elektronların bulunması', ['Grafitin elmastan daha yoğun olması nedeniyle atomların birbirine daha çok yaklaşması', 'Elmasın daha sıcak olması', 'Grafitin içinde metal iyonları bulunması'], 'Grafitte her karbon atomunun bir elektronu katmanlar boyunca serbestçe hareket edebilir. Elmasta bütün değerlik elektronları bağlarda tutulduğundan iletim olmaz.'),
  ('Aşağıdaki durumlardan hangisinde metal bir telin direnci en çok artar?', 'Uzunluğu iki katına çıkarılıp çapı yarıya indirilirse', ['Uzunluğu yarıya indirilirse', 'Çapı iki katına çıkarılırsa', 'Sıcaklığı 10 °C azaltılırsa'], 'Uzunluk iki katına çıkınca direnç 2 katına, çap yarıya inince alan dörtte birine düşüp direnç 4 katına çıkar. Toplam etki 8 kattır; diğer seçeneklerde direnç azalır.'),
  ('Sürekli çalışan bir elektrik motorunun bobin telleri aşırı ısındığında motorun veriminde ne olur?', 'Bobin direnci artar, I²R kaybı büyür ve verim azalır', ['Motor verimi artar çünkü direnç azalır', 'Verim değişmez çünkü ısı enerji kaybı değildir', 'Bobin direnci sıfır olur'], 'Metal bobinin direnci sıcaklıkla artar; aynı akımda I²R ısı kaybı büyür ve motorun verimi düşer.'),
  ('Bir evde 10 cihaz her biri bekleme modunda ortalama 3 W güç çekerek yıl boyunca prizde kalıyor. 1 kWh = 2 lira alınırsa bekleme tüketiminin yıllık maliyeti yaklaşık kaç liradır?', '526 lira', ['52,6 lira', '263 lira', '1052 lira'], 'Toplam güç 30 W\'tır. Yıllık enerji 0,03 kW × 8760 h = 262,8 kWh\'tir. Maliyet 262,8 × 2 ≈ 526 liradır.'),
  ('Her biri 6 V – 3 W olan dört lamba, ikişerli seri iki kol oluşturup bu kollar paralel bağlanarak 12 V\'luk bir bataryaya takılıyor. Bataryadan çekilen toplam akım kaç amperdir?', '1 A', ['0,5 A', '2 A', '4 A'], 'Her kolda iki lamba 12 V\'u paylaşır ve her biri 6 V alır; her lamba 0,5 A çeker. Kol akımı 0,5 A, iki kolun toplamı 1 A\'dir.'),
  ('220 V\'luk 16 A\'lik bir hatta, her biri 1 kW olan elektrikli ısıtıcılardan en çok kaç tanesi aynı anda çalıştırılabilir?', '3 tane', ['2 tane', '4 tane', '16 tane'], 'Hattın taşıyabileceği güç 220 × 16 = 3520 W\'tır. 1 kW\'lık dört ısıtıcı 4000 W çeker ve sigortayı attırır; en çok 3 ısıtıcı çalıştırılabilir.'),
  ('Bir elektrik süpürgesini daha uzun kablo kullanarak çalıştıran kişi, motorun daha az güçlü çalıştığını hissediyor. Bunun fiziksel nedeni nedir?', 'Uzun kablonun direncinde gerilim düşer ve motora ulaşan gerilim azalır', ['Kablo uzadıkça şebeke gerilimi artar', 'Kablonun direnci uzunlukla azalır', 'Motorun direnci kablo uzadıkça sıfıra iner'], 'Kablonun direnci uzunlukla orantılı artar. Motor akımı kabloda I·R gerilim düşümü yaratır; motora ulaşan gerilim ve güç azalır.'),
  ('Bir elektrik devresinde sürekli ısınan bir bağlantı noktası tespit edilmiştir. Bu noktadaki sorunun başlıca nedeni ve doğru önlemi aşağıdakilerden hangisidir?', 'Temas direnci yüksektir; bağlantı sıkıştırılıp yenilenmelidir', ['Temas direnci sıfırdır; bağlantı gevşetilmelidir', 'Gerilim çok düşüktür; pil artırılmalıdır', 'Akım ters yöndedir; kutuplar değiştirilmelidir'], 'Gevşek ya da oksitlenmiş bir bağlantıda temas direnci yüksektir ve I²R ısısı oluşur. Doğru önlem, bağlantıyı temizleyip sağlam biçimde sıkmak ya da yenilemektir.'),
  ('5 V\'luk kaynağa silisyum bir diyot (eşik 0,7 V), bir LED (2 V) ve bir R direnci ileri yönde seri bağlıdır. Devreden 10 mA geçmesi için R kaç ohm olmalıdır?', '230 Ω', ['500 Ω', '130 Ω', '300 Ω'], 'R\'de düşen gerilim 5 − 0,7 − 2 = 2,3 V olmalıdır. R = 2,3/0,01 = 230 Ω\'dur.'),
  ('Akım kazancı β = 100 olan bir transistörün aktif bölgede çalıştığı bir devrede taban akımı 0,2 mA ise kollektör akımı kaç miliamperdir?', '20 mA', ['0,002 mA', '200 mA', '0,2 mA'], 'Aktif bölgede I_C = β·I_B = 100 × 0,2 mA = 20 mA\'dir.'),
  ('Metre köprüsünde bilinmeyen X direnci sol aralığa, 8 Ω\'luk standart direnç sağ aralığa bağlanmıştır. Galvanometre telin sol ucundan 60 cm uzaklıkta sıfır gösteriyorsa (tel 100 cm) X kaç ohmdur?', '12 Ω', ['5,33 Ω', '8 Ω', '4,8 Ω'], 'Denge koşulu X/8 = l₁/l₂ = 60/40\'tır. X = 8 × 1,5 = 12 Ω bulunur.'),
  ('Dengelenmiş bir Wheatstone köprüsünde kaynak gerilimi iki katına çıkarılırsa köprünün dengesi nasıl etkilenir?', 'Denge bozulmaz, köprü kolundan yine akım geçmez', ['Denge bozulur, galvanometre sapar', 'Köprü kolundan iki kat akım geçer', 'Denge yalnız akım azalırsa sürer'], 'Denge koşulu yalnızca direnç oranlarına bağlıdır, kaynak gerilimine bağlı değildir. Gerilim değişse de köprü uçları aynı potansiyelde kalır.'),
  ('İki özdeş lamba birbirine seri bağlanıp ideal bir kaynağa takılmıştır; bu seri kola, kaynağın uçları arasında paralel olarak ayrıca bir R direnci bağlanmıştır. R\'nin değeri artırılırsa lambaların parlaklığı nasıl değişir?', 'Değişmez, çünkü seri kolun gerilimi kaynak gerilimine eşit kalır', ['Artar, çünkü paralel direnç büyüdükçe lambalardan geçen akım artar', 'Azalır, çünkü toplam direnç artar ve akım küçülür', 'Lambalar söner, çünkü paralel kol akımı keser'], 'İdeal kaynağın uçlarındaki gerilim sabittir. Seri lamba kolu doğrudan bu gerilimi alır; paralel R\'nin değişmesi bu kolun akımını etkilemez ve parlaklık aynı kalır.'),
  ('Nominal gerilimi 3,85 V ve kapasitesi 4500 mAh olan bir telefon bataryası, 15 W\'lık bir hızlı şarj cihazıyla (kayıplar ihmal) boştan doluya yaklaşık kaç saatte dolar?', '1,2 saat', ['0,3 saat', '3,85 saat', '12 saat'], 'Batarya enerjisi 3,85 × 4,5 ≈ 17,3 Wh\'tir. Süre = 17,3/15 ≈ 1,2 saattir; gerçekte kayıplar ve akım sınırlaması nedeniyle biraz daha uzun sürer.'),
  ('Kesit alanı 1,5 mm² olan bakır bir kablonun (ρ = 1,7 × 10⁻⁸ Ω·m) gidiş-dönüş toplam uzunluğu 20 m\'dir. Bu kabloda 10 A akım geçerken gerilim düşümü yaklaşık kaç volttur?', '2,27 V', ['0,227 V', '22,7 V', '0,5 V'], 'Kablo direnci R = ρL/A = 1,7×10⁻⁸ × 20 / 1,5×10⁻⁶ ≈ 0,227 Ω\'dur. Gerilim düşümü I·R = 10 × 0,227 ≈ 2,27 V\'tur.'),
  ('1 mAh\'lik yük kaç tane elektronun yüküne eşdeğerdir? (e = 1,6 × 10⁻¹⁹ C)', '2,25 × 10¹⁹', ['6,25 × 10¹⁸', '3,6 × 10⁻³', '2,25 × 10¹⁶'], '1 mAh = 3,6 C\'dir. Elektron sayısı n = 3,6 / 1,6×10⁻¹⁹ = 2,25×10¹⁹\'dur.'),
  ('3 V ve 220 mAh\'lik bir saat pili, yaklaşık 0,02 mA ortalama akım çeken bir saati yaklaşık ne kadar çalıştırır?', 'Yaklaşık 1,25 yıl', ['Yaklaşık 11 saat', 'Yaklaşık 12 yıl', 'Yaklaşık 1 ay'], 'Süre = 220 mAh / 0,02 mA = 11 000 saattir; bu yaklaşık 11 000/8760 ≈ 1,25 yıldır.'),
  ('Her biri 1,5 V – 1000 mAh olan dört pilden ikişerli seri iki grup yapılıp bu gruplar paralel bağlanıyor. Bileşimin gerilimi, kapasitesi ve depoladığı toplam enerji nedir?', '3 V, 2000 mAh, 6 Wh', ['6 V, 1000 mAh, 6 Wh', '1,5 V, 4000 mAh, 6 Wh', '3 V, 1000 mAh, 3 Wh'], 'İki seri pil 3 V yapar, iki grubun paralel bağlanması kapasiteyi 2000 mAh yapar. Enerji = 3 V × 2 Ah = 6 Wh\'tir (4 pilin toplam enerjisi).'),
  ('Bir elektron, devrede pilden direnç üzerinden geçerek dolaşırken enerji alışverişi bakımından aşağıdakilerden hangisi doğrudur?', 'Pilde potansiyel enerji kazanır, dirençte bu enerjiyi örgüye çarpmalarla ısı olarak bırakır', ['Dirençte enerji kazanır, pilde enerji kaybeder', 'Hiç enerji alışverişi yapmaz', 'Dirençte kinetik enerjisini sürekli artırır'], 'Pil, yüklere potansiyel enerji kazandırır. Direnç içindeki yükler örgüyle çarpışarak bu enerjiyi ısıya aktarır; sürüklenme hızı ise hemen hemen sabit kalır.'),
  ('Bir metal telde sabit elektrik alan altında elektronların ivmelenmeye devam etmek yerine yaklaşık sabit bir ortalama sürüklenme hızına ulaşmasının nedeni nedir?', 'Örgü iyonlarıyla çarpışmalar elektronların kazandığı momentumu sürekli sıfırlar', ['Elektrik alanın zamanla sıfırlanması', 'Elektronların kütlesinin hızla artması', 'Elektronların yüklerini kaybetmesi'], 'Elektronlar alan tarafından ivmelenir ama örgüyle çarpışınca momentumlarını kaybeder. İvmelenme ile çarpışma dengesi ortalama sabit bir sürüklenme hızı sağlar.'),
  ('10 V\'luk ideal kaynağa 2 Ω\'luk bir direnç, birbirine paralel 3 Ω ve 6 Ω\'luk dirençlerle seri bağlıdır. 6 Ω\'luk dirençte harcanan güç kaç watt olur?', '4,17 W', ['25 W', '12,5 W', '8,33 W'], 'Paralel grup 2 Ω, toplam 4 Ω; ana akım 2,5 A\'dir. Gruptaki gerilim 5 V; 6 Ω\'da P = 25/6 ≈ 4,17 W\'tır.'),
  ('Bir direncin değeri R, kondansatörün sığası C iken RC çarpımının SI birimi hangi birime eşittir?', 'Saniye', ['Hertz', 'Joule', 'Coulomb'], 'Ω·F = (V/A)·(C/V) = C/A = s olduğundan RC çarpımının birimi saniyedir.'),
  ('Bir devre elemanının iki ucu arasında potansiyel farkı yoksa o elemandan geçen akım için ne söylenebilir?', 'Direnç varsa akım sıfırdır; ideal iletkenle bağlıysa akım serbestçe geçebilir', ['Akım mutlaka en büyüktür', 'Akım her durumda sonsuzdur', 'Akım yön değiştirir'], 'Direnç üzerinden akım geçmesi için gerilim gerekir (I = V/R). Gerilim sıfırsa sıfır dirençli bir yolda akım serbestçe geçebilse de omik dirençten akım geçmez.'),
  ('AgNO₃ çözeltisinden 1 A\'lik akım 9650 saniye geçirilirse katotta yaklaşık kaç gram gümüş toplanır? (Ag: 108 g/mol, Ag⁺, 1 mol elektronun yükü 96 500 C)', '10,8 g', ['1,08 g', '21,6 g', '108 g'], 'Geçen yük 9650 C\'dur; bu 0,1 mol elektrona karşılık gelir. Ag⁺ için 0,1 mol Ag, yani 10,8 g toplanır.'),
  ('Sabit akımla yapılan bir elektrolizde akım iki katına çıkarılır ve süre yarıya indirilirse katotta toplanan madde miktarı nasıl değişir?', 'Değişmez', ['İki katına çıkar', 'Yarıya iner', 'Dört katına çıkar'], 'Toplanan kütle geçen yük ile orantılıdır. Q = I·t olduğundan akım iki katına çıkıp süre yarıya inince yük aynı kalır.'),
  ('Bir elektrik devresinde ampermetre 0,8 A ve voltmetre 4 V göstermektedir (ideal aletler). Bu eleman 5 dakika çalıştığında açığa çıkan enerji kaç joule\'dür?', '960 J', ['16 J', '1920 J', '192 J'], 'Güç P = V·I = 4 × 0,8 = 3,2 W\'tır. Enerji = 3,2 × 300 s = 960 J\'dür.'),
  ('Bir üretecin dış direnci sonsuza doğru büyütülürse üretecin verimi ve dış devreye verdiği güç nasıl değişir?', 'Verim %100\'e yaklaşır, dış güç sıfıra yaklaşır', ['Verim ve güç birlikte artar', 'Verim sıfıra yaklaşır, güç sonsuza gider', 'Verim ve güç değişmez'], 'R → ∞ iken akım sıfıra gider; iç dirençteki kayıp ihmal edilebilir ve verim R/(R + r) → %100 olur, ancak P = I²R de sıfıra yaklaşır.'),
  ('Üç özdeş lamba seri bağlanıp ideal bir kaynağa takılmıştır ve ampermetre 0,5 A göstermektedir. Lambalardan biri devreden çıkarılıp uçları iletken telle birleştirilirse ampermetre kaç amper gösterir?', '0,75 A', ['0,5 A', '1,5 A', '0,125 A'], 'Üç lambada I = V/3R = 0,5 A ise V/R = 1,5 A\'dir. İki lambada I = V/2R = 0,75 A olur.'),
  ('Emk\'ları 6 V ve 4 V olan iki pil, iç dirençleri 0,5 Ω olacak biçimde zıt kutuplar birbirine bakacak şekilde seri bağlanıp 4 Ω\'luk bir dirence takılıyor. Devreden geçen akım kaç amperdir?', '0,4 A', ['2 A', '0,04 A', '1 A'], 'Net emk 6 − 4 = 2 V, toplam direnç 4 + 0,5 + 0,5 = 5 Ω\'dur. I = 2/5 = 0,4 A\'dir.'),
  ('Bir ısıtıcının rezistans teli tam ortasından ikiye kesilip iki parça birbirine paralel bağlanarak aynı şebekeye takılırsa ısıtıcının gücü ilk değerinin kaç katı olur?', '4 katı', ['2 katı', '1/2 katı', '8 katı'], 'Her yarının direnci R/2\'dir; paralel eşdeğeri R/4 olur. Aynı gerilimde P = V²/R olduğundan güç 4 katına çıkar.'),
  ('Beş bantlı bir direncin bantları sırasıyla kırmızı, kırmızı, siyah, kahverengi ve kahverengidir (kırmızı 2, siyah 0, kahverengi 1; dördüncü bant çarpan, beşinci bant %1 tolerans). Direncin değeri nedir?', '2200 Ω, ±%1', ['220 Ω, ±%1', '2200 Ω, ±%5', '22 000 Ω, ±%1'], 'İlk üç bant 2, 2 ve 0 rakamlarını (220) verir; dördüncü bant ×10 çarpanıdır. Değer 220 × 10 = 2200 Ω ve tolerans ±%1\'dir.'),
  ('Yüzey montajlı (SMD) bir direncin üzerinde \'472\' yazmaktadır. Direncin değeri nedir?', '4,7 kΩ', ['472 Ω', '47,2 kΩ', '4,72 Ω'], 'İlk iki rakam anlamlı basamaklar (47), üçüncü rakam sıfır sayısıdır (2): 47 × 10² = 4700 Ω = 4,7 kΩ.'),
  ('Bir seramik kondansatörün üzerinde \'104\' yazmaktadır (değer pikofarad cinsindendir). Kondansatörün sığası nedir?', '100 nF', ['104 pF', '10 nF', '1 μF'], 'Kodda ilk iki rakam anlamlıdır (10), üçüncü rakam sıfır sayısıdır (4): 10 × 10⁴ pF = 100 000 pF = 100 nF = 0,1 μF.'),
  ('Standart E12 direnç serisinde 47 Ω\'dan sonra gelen bir sonraki değer hangisidir?', '56 Ω', ['50 Ω', '51 Ω', '60 Ω'], 'E12 serisi 10, 12, 15, 18, 22, 27, 33, 39, 47, 56, 68, 82 değerlerini içerir; 47\'den sonra 56 gelir.'),
  ('Elinizde 1 kΩ\'luk dirençler var ve 1,5 kΩ gerekiyor. Aşağıdakilerden hangisi bu değeri verir?', 'İki direnç paralel, bu grup bir dirençle seri', ['Üç direnç seri', 'Üç direnç paralel', 'İki direnç seri, bu grup bir dirençle paralel'], 'İki 1 kΩ paralel 0,5 kΩ eder; buna 1 kΩ seri eklenince 1,5 kΩ elde edilir. İki seri + bir paralel ise 0,67 kΩ verir.'),
  ('Analog bir ohmmetrede ölçüm uçları birbirine doğrudan değdirilirse (sıfır direnç) ibre nasıl davranır?', 'İbre tam ölçeğe, yani skalanın sıfır ohm ucuna sapar', ['İbre skalanın sonsuz direnç ucunda kalır', 'İbre sürekli titreşir ve ölçüm yapmaz', 'İbre devrenin gerilimini gösterir'], 'Ohmmetre kendi pilinden akım gönderir. Uçlar kısa devre edilince devreden en büyük akım geçer ve ibre en uç noktaya, yani 0 Ω işaretine sapar.'),
  ('10 V\'a yüklenmiş bir kondansatör 1 kΩ\'luk bir dirençten boşalıyor. Boşalmaya başladıktan tam bir zaman sabiti (τ = RC) sonra devre akımı yaklaşık kaç miliamperdir? (e⁻¹ ≈ 0,37)', '3,7 mA', ['10 mA', '6,3 mA', '1 mA'], 'İlk akım V₀/R = 10 mA\'dir. Boşalmada akım e^(−t/τ) ile azalır; t = τ için I ≈ 10 × 0,37 = 3,7 mA\'dir.'),
  ('Bir kalp defibrilatörünün kondansatörü depoladığı 875 J enerjiyi yaklaşık 10 ms\'de boşaltıyor. Bu sürede ortalama güç yaklaşık kaç kilowatt\'tır?', '87,5 kW', ['8,75 kW', '875 kW', '0,875 kW'], 'Ortalama güç = enerji/süre = 875 J / 0,010 s = 87 500 W = 87,5 kW\'tır.'),
  ('Bir lambada 2 V\'ta 0,10 A, 6 V\'ta 0,20 A ölçülüyor. Bu ölçümler lambanın direnci hakkında ne gösterir?', 'Direnç 20 Ω\'dan 30 Ω\'a artmıştır; flaman ısındıkça direnç yükselir', ['Direnç sabittir ve 20 Ω\'dur', 'Direnç 30 Ω\'dan 20 Ω\'a azalmıştır', 'Direnç 0,05 Ω\'dur'], 'V/I oranı 2/0,10 = 20 Ω\'dan 6/0,20 = 30 Ω\'a çıkmıştır. Gerilim arttıkça flaman ısınır ve metalin direnci artar.'),
  ('Her biri 18 V ve 5 A veren özdeş 6 güneş paneli, 3 seri × 2 paralel olacak biçimde bağlanıyor. Panel grubunun toplam gerilimi, akımı ve gücü nedir?', '54 V, 10 A, 540 W', ['108 V, 5 A, 540 W', '18 V, 30 A, 540 W', '54 V, 5 A, 270 W'], 'Üç panel seri 54 V, iki grubun paralel bağlanması akımı 10 A yapar. Güç 54 × 10 = 540 W\'tır (6 panelin toplamı).'),
  ('Seri bağlı güneş paneli dizisinde bir panelin üzeri gölgelenirse tüm dizinin çıkışı neden belirgin biçimde düşer?', 'Seri devrede akım ortaktır; gölgelenen panel akımı sınırlar', ['Gölge gerilimi ters çevirir', 'Güneş ışığı seri panellerde bölünür', 'Gölgelenen panel akımı artırır'], 'Seri dizide aynı akım tüm panellerden geçer. Işık alan miktarı azalmış panelin akım üretimi düşük olduğundan diziyi kendi seviyesinde tutar.'),
  ('Her biri 12 V ve 100 Ah olan dört akü seri bağlanıyor. Bu akü bankasının gerilimi ve toplam depoladığı enerji nedir?', '48 V ve 4,8 kWh', ['12 V ve 4,8 kWh', '48 V ve 1,2 kWh', '12 V ve 400 Ah, 1,2 kWh'], 'Seri bağlamada gerilim 48 V olur, kapasite 100 Ah kalır. Enerji 48 × 100 = 4800 Wh = 4,8 kWh\'tır.'),
  ('Gerinim ölçerlerde (strain gauge) dirençteki bağıl değişim ΔR/R, uzamanın iki katı kadardır (ölçüm katsayısı 2). 120 Ω\'luk bir gerinim ölçer %0,1 uzarsa direnci kaç ohm artar?', '0,24 Ω', ['0,12 Ω', '2,4 Ω', '0,024 Ω'], 'ΔR/R = 2 × 0,001 = 0,002 olduğundan ΔR = 0,002 × 120 = 0,24 Ω\'dur.'),
  ('Parmakla dokunmatik ekrana dokunulduğunda kapasitif algılamanın çalışması aşağıdakilerden hangisine dayanır?', 'Parmağın ekran üzerindeki bölgenin sığasını değiştirmesine', ['Parmağın ekranı ısıtmasına', 'Parmağın ekran direncini sıfırlamasına', 'Parmağın ekrana basınç uygulamasına'], 'Kapasitif ekranda iletken parmak ekran elektrotlarıyla bir sığa oluşturur veya mevcut sığayı değiştirir; bu değişim algılanarak dokunma konumu belirlenir.'),
  ('Anma gücü 3 MW olan bir rüzgâr türbininin yıllık kapasite faktörü %35\'tir. Bir yılda ürettiği enerji yaklaşık kaç MWh\'tir?', '9200 MWh', ['26 280 MWh', '920 MWh', '3000 MWh'], 'Tam güçte yıllık enerji 3 × 8760 = 26 280 MWh\'tir. Kapasite faktörü %35 ile bu 26 280 × 0,35 ≈ 9198 MWh eder.'),
  ('Anma gücü 1 kW olan bir güneş paneli sistemi bir yılda 1500 kWh üretiyorsa yıllık kapasite faktörü yaklaşık yüzde kaçtır?', '%17', ['%1,7', '%50', '%100'], 'Sürekli tam güçte yıllık enerji 1 kW × 8760 h = 8760 kWh olurdu. Oran 1500/8760 ≈ 0,17 yani %17\'dir.'),
  ('1000 MW\'lık güç 400 kV\'luk bir hatla iletiliyorsa hattan geçen akım yaklaşık kaç amperdir?', '2500 A', ['250 A', '25 000 A', '0,4 A'], 'I = P/V = 10⁹ / (4×10⁵) = 2500 A\'dir.'),
  ('Bir milyon haneli bir şehirde her hane günde ortalama 3 kWh elektrik tüketiyorsa şehrin ortalama elektrik gücü kaç megawattır?', '125 MW', ['3 MW', '3000 MW', '12,5 MW'], 'Günlük enerji 3 000 000 kWh = 3000 MWh\'tir. Ortalama güç 3000/24 = 125 MW\'tır.'),
  ('Doğru akımlı 1,5 kV\'luk bir hattan beslenen 1,2 MW\'lık bir elektrikli tren, hattan kaç amper akım çeker?', '800 A', ['1800 A', '80 A', '1,25 A'], 'I = P/V = 1,2×10⁶ / 1500 = 800 A\'dir.'),
  ('1 MWh enerji kaç gigajoule\'dür?', '3,6 GJ', ['0,36 GJ', '36 GJ', '1 GJ'], '1 MWh = 10⁶ W × 3600 s = 3,6×10⁹ J = 3,6 GJ\'dür.'),
  ('Santralin verimi %40, iletim hattı verimi %92 ve elektrik motorunun verimi %85 ise yakıt enerjisinden motor miline ulaşan enerjinin oranı yaklaşık yüzde kaçtır?', '%31', ['%72', '%217', '%92'], 'Verimler çarpılır: 0,40 × 0,92 × 0,85 ≈ 0,313 yani yaklaşık %31\'dir.'),
  ('10 000 sokak lambasının her biri 150 W\'lık armatürden 50 W\'lık LED\'e dönüştürülüyor. Her lamba gecede 10 saat yanıyorsa şehir bir gecede kaç MWh enerji tasarruf eder?', '10 MWh', ['1 MWh', '100 MWh', '15 MWh'], 'Güç tasarrufu lamba başına 100 W\'tır. Toplam enerji 0,1 kW × 10 000 × 10 h = 10 000 kWh = 10 MWh\'tir.'),
  ('60 kWh\'lik bir araç bataryası, verimi %90 olan bir şarj cihazıyla tamamen doldurulursa şebekeden çekilen enerji yaklaşık kaç kWh olur?', '66,7 kWh', ['54 kWh', '60 kWh', '90 kWh'], 'Şebekeden çekilen enerji, batarya enerjisinin verime bölünmesiyle bulunur: 60/0,9 ≈ 66,7 kWh.'),
  ('Seri bağlı iki dirençten oranı R₁ : R₂ = 1 : 3\'tür. Toplam harcanan güç P ise R₂\'nin harcadığı güç kaç P\'dir?', '3P/4', ['P/4', '5P/12', '2P/3'], 'Seri devrede akım ortaktır ve P = I²R olduğundan güçler dirençlerle orantılıdır. R₂, toplam direncin 3/4\'ü olduğundan gücün 3/4\'ünü harcar.'),
  ('Dört özdeş lamba, aynı kaynağa bir kez dördü seri, bir kez dördü paralel bağlanıyor. Paralel düzenin toplam gücü seri düzenin toplam gücünün kaç katıdır?', '16 katı', ['4 katı', '8 katı', '2 katı'], 'Seri eşdeğer 4R, paralel eşdeğer R/4\'tür. Aynı gerilimde güç oranı 4R/(R/4) = 16\'dır.'),
  ('Üç özdeş 6 μF\'lık kondansatör seri bağlanıp 12 V\'a bağlanıyor. Toplam depolanan enerji kaç mikrojoule\'dür?', '144 μJ', ['432 μJ', '1440 μJ', '864 μJ'], 'Eşdeğer sığa 2 μF\'tır. U = ½CV² = 0,5 × 2×10⁻⁶ × 144 = 1,44×10⁻⁴ J = 144 μJ\'dür.'),
  ('Hassasiyeti 20 kΩ/V olan bir voltmetrenin 10 V\'luk kademesindeki iç direnci kaç kΩ\'dur?', '200 kΩ', ['2 kΩ', '20 kΩ', '0,5 kΩ'], 'İç direnç = hassasiyet × tam ölçek gerilimi = 20 kΩ/V × 10 V = 200 kΩ\'dur.'),
  ('Aynı kalınlıkta bir bakır (ρ ≈ 1,7 × 10⁻⁸ Ω·m) ve bir demir (ρ ≈ 10 × 10⁻⁸ Ω·m) tel aynı dirence sahip olacaksa demir telin uzunluğu bakır telin uzunluğunun yaklaşık kaç katı olmalıdır?', '0,17 katı', ['5,9 katı', '1 katı', '0,017 katı'], 'Aynı kesit ve aynı R için L, özdirençle ters orantılıdır: L_Fe/L_Cu = ρ_Cu/ρ_Fe = 1,7/10 = 0,17.'),
];
